export default [{"id":"494","jozz":"4","page":"77","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"5","aya_no":"1","aya_text":"يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالٗا كَثِيرٗا وَنِسَآءٗۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا","aya_text_emlaey":"ياأيها الناس اتقوا ربكم الذي خلقكم من نفس واحدة وخلق منها زوجها وبث منهما رجالا كثيرا ونساء واتقوا الله الذي تساءلون به والأرحام إن الله كان عليكم رقيبا","aya_tafseer":"[1] يا أيها الناس خافوا الله والتزموا أوامره، واجتنبوا نواهيه؛ فهو الذي خلقكم من نفس واحدة هي آدم عليه السلام، وخلق منها زوجها وهي حواء، ونشر منهما في أنحاء الأرض رجالاً كثيراً ونساء كثيرات، وراقبوا الله الذي يَسْأل به بعضكم بعضاً، واحذروا أن تقطعوا أرحامكم. إن الله مراقب لجميع أحوالكم."},{"id":"495","jozz":"4","page":"77","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"5","line_end":"6","aya_no":"2","aya_text":"وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبٗا كَبِيرٗا","aya_text_emlaey":"وآتوا اليتامى أموالهم ولا تتبدلوا الخبيث بالطيب ولا تأكلوا أموالهم إلى أموالكم إنه كان حوبا كبيرا","aya_tafseer":"[2] وأعطوا مَن مات آباؤهم وهم دون البلوغ -وكنتم عليهم أوصياء- أموالهم إذا وصلوا سن البلوغ، ورأيتم منهم قدرة على حفظ أموالهم، ولا تأخذوا الجيِّد من أموالهم، وتجعلوا مكانه الرديء من أموالكم، ولا تخلطوا أموالهم بأموالكم؛ لتحتالوا بذلك على أكل أموالهم. إنَّ مَن تجرَّأ على ذلك فقد ارتكب إثماً عظيماً."},{"id":"496","jozz":"4","page":"77","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"9","aya_no":"3","aya_text":"وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ ذَٰلِكَ أَدۡنَىٰٓ أَلَّا تَعُولُواْ","aya_text_emlaey":"وإن خفتم ألا تقسطوا في اليتامى فانكحوا ما طاب لكم من النساء مثنى وثلاث ورباع فإن خفتم ألا تعدلوا فواحدة أو ما ملكت أيمانكم ذلك أدنى ألا تعولوا","aya_tafseer":"[3] وإن خفتم ألا تعدلوا في يتامى النساء اللاتي تحت أيديكم بأن لا تعطوهن مهورهن كغيرهن، فاتركوهن وانكحوا ما طاب لكم من النساء من غيرهن: اثنتين أو ثلاثاً أو أربعاً، فإن خشيتم ألَّا تعدلوا بينهن فاكتفوا بواحدة، أو بما عندكم من الإماء. ذلك الذي شرعته لكم في اليتيمات والزواج من واحدة إلى أربع، أو الاقتصار على واحدة أو ملك اليمين، أقرب إلى عدم الجَوْر والتعدي."},{"id":"497","jozz":"4","page":"77","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"10","aya_no":"4","aya_text":"وَءَاتُواْ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةٗۚ فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ هَنِيٓـٔٗا مَّرِيٓـٔٗا","aya_text_emlaey":"وآتوا النساء صدقاتهن نحلة فإن طبن لكم عن شيء منه نفسا فكلوه هنيئا مريئا","aya_tafseer":"[4] وأعطوا -أيها الأزواج- النساء مهورهن، عطية واجبة وفريضة لازمة عن طيب نفس منكم. فإن طابت أنفسهن لكم عن شيء من المهر فوهَبْنه لكم فخذوه، وتصرَّفوا فيه، فهو حلال طيب."},{"id":"498","jozz":"4","page":"77","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"12","aya_no":"5","aya_text":"وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا وَٱرۡزُقُوهُمۡ فِيهَا وَٱكۡسُوهُمۡ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا","aya_text_emlaey":"ولا تؤتوا السفهاء أموالكم التي جعل الله لكم قياما وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا","aya_tafseer":"[5] ولا تؤتوا -أيها الأولياء- من يُبَذِّر من الرجال والنساء والصبيان أموالهم التي تحت أيديكم فيضعوها في غير وجهها، فهذه الأموال هي التي عليها قيام حياة الناس، وأنفقوا عليهم منها واكسوهم، وقولوا لهم قولاً معروفاً من الكلام الطيب والخلق الحسن."},{"id":"499","jozz":"4","page":"77","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"15","aya_no":"6","aya_text":"وَٱبۡتَلُواْ ٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ وَمَن كَانَ غَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا","aya_text_emlaey":"وابتلوا اليتامى حتى إذا بلغوا النكاح فإن آنستم منهم رشدا فادفعوا إليهم أموالهم ولا تأكلوها إسرافا وبدارا أن يكبروا ومن كان غنيا فليستعفف ومن كان فقيرا فليأكل بالمعروف فإذا دفعتم إليهم أموالهم فأشهدوا عليهم وكفى بالله حسيبا","aya_tafseer":"[6] واختبروا مَن تحت أيديكم من اليتامى لمعرفة قدرتهم على حسن التصرف في أموالهم، حتى إذا وصلوا إلى سن البلوغ، وعَلمتم منهم صلاحاً في دينهم، وقدرة على حفظ أموالهم، فسلِّموها لهم، ولا تعتدوا عليها بإنفاقها في غير موضعها إسرافاً ومبادرة لأكلها قبل أن يكبَروا فيأخذوها منكم. ومَن كان صاحب مال منكم فليستعفف بغناه، ولا يأخذ من مال اليتيم شيئاً، ومن كان فقيراً فليأخذ بقدر حاجته عند الضرورة. فإذا علمتم أنهم قادرون على حفظ أموالهم بعد بلوغهم الحُلُم وسلمتموها إليهم، فأَشْهِدوا عليهم؛ ضماناً لوصول حقهم كاملاً إليهم؛ ولئلا ينكروا ذلك. ويكفيكم أن الله شاهد عليكم، ومحاسب لكم على ما فعلتم."},{"id":"500","jozz":"4","page":"78","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"3","aya_no":"7","aya_text":"لِّلرِّجَالِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِيبٗا مَّفۡرُوضٗا","aya_text_emlaey":"للرجال نصيب مما ترك الوالدان والأقربون وللنساء نصيب مما ترك الوالدان والأقربون مما قل منه أو كثر نصيبا مفروضا","aya_tafseer":"[7] للذكور -صغاراً أو كباراً- نصيب شرعه الله فيما تركه الوالدان والأقربون من المال، قليلاً كان أو كثيراً، في أنصبة محددة واضحة فرضها الله عز وجل لهؤلاء، وللنساء كذلك."},{"id":"501","jozz":"4","page":"78","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"4","aya_no":"8","aya_text":"وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا","aya_text_emlaey":"وإذا حضر القسمة أولو القربى واليتامى والمساكين فارزقوهم منه وقولوا لهم قولا معروفا","aya_tafseer":"[8] وإذا حضر قسمةَ الميراث أقاربُ الميت ممن لا حقَّ لهم في التركة، أو حضرها مَن مات آباؤهم وهم صغار دون سن البلوغ، أو مَن لا يملكون ما يكفيهم ويسدُّ حاجتهم، فأعطوهم شيئاً من المال على وجه الاستحباب قبل تقسيم التركة على أصحابها، وقولوا لهم قولاً حسناً غير فاحش ولا قبيح."},{"id":"502","jozz":"4","page":"78","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"5","line_end":"6","aya_no":"9","aya_text":"وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةٗ ضِعَٰفًا خَافُواْ عَلَيۡهِمۡ فَلۡيَتَّقُواْ ٱللَّهَ وَلۡيَقُولُواْ قَوۡلٗا سَدِيدًا","aya_text_emlaey":"وليخش الذين لو تركوا من خلفهم ذرية ضعافا خافوا عليهم فليتقوا الله وليقولوا قولا سديدا","aya_tafseer":"[9] ولْيَخَفِ الذين لو ماتوا وتركوا من خلفهم أبناء صغاراً ضعافاً خافوا عليهم الظلم والضياع، فليراقبوا الله فيمن تحت أيديهم من اليتامى وغيرهم، وذلك بحفظ أموالهم، وحسن تربيتهم، ودَفْع الأذى عنهم، وليقولوا لهم قولاً موافقاً للعدل والمعروف."},{"id":"503","jozz":"4","page":"78","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"8","aya_no":"10","aya_text":"إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ وَسَيَصۡلَوۡنَ سَعِيرٗا","aya_text_emlaey":"إن الذين يأكلون أموال اليتامى ظلما إنما يأكلون في بطونهم نارا وسيصلون سعيرا","aya_tafseer":"[10] إن الذين يَعْتَدون على أموال اليتامى، فيأخذونها بغير حق، إنما يأكلون ناراً تتأجج في بطونهم يوم القيامة، وسيدخلون ناراً يقاسون حرَّها."},{"id":"504","jozz":"4","page":"78","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"15","aya_no":"11","aya_text":"يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءٗ فَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٞۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدٞ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥٓ إِخۡوَةٞ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعٗاۚ فَرِيضَةٗ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا","aya_text_emlaey":"يوصيكم الله في أولادكم للذكر مثل حظ الأنثيين فإن كن نساء فوق اثنتين فلهن ثلثا ما ترك وإن كانت واحدة فلها النصف ولأبويه لكل واحد منهما السدس مما ترك إن كان له ولد فإن لم يكن له ولد وورثه أبواه فلأمه الثلث فإن كان له إخوة فلأمه السدس من بعد وصية يوصي بها أو دين آباؤكم وأبناؤكم لا تدرون أيهم أقرب لكم نفعا فريضة من الله إن الله كان عليما حكيما","aya_tafseer":"[11] يوصيكم الله ويأمركم في شأن أولادكم: إذا مات أحد منكم وترك أولاداً: ذكوراً وإناثاً، فميراثه كله لهم: للذكر مثل نصيب الأنثيين، إذا لم يكن هناك وارث غيرهم. فإن ترك بنات فقط فللبنتين فأكثر ثلثا ما ترك، وإن كانت ابنة واحدة، فلها النصف. ولوالِدَي الميت لكل واحد منهما السدس إن كان له ولد: ذكراً كان أو أنثى، واحداً أو أكثر. فإن لم يكن له ولد وورثه والداه فلأمه الثلث ولأبيه الباقي. فإن كان للميت إخوة اثنان فأكثر، ذكوراً كانوا أو إناثاً، فلأمه السدس، وللأب الباقي ولا شيء للإخوة. وهذا التقسيم للتركة إنما يكون بعد إخراج وصية الميت في حدود الثلث، أو إخراج ما عليه من دَيْن. آباؤكم وأبْناؤكم الذين فُرِض لهم الإرث لا تعرفون أيهم أقرب لكم نفعاً في دنياكم وأخراكم، فلا تفضلوا واحداً منهم على الآخر. هذا الذي أوصيتكم به مفروض عليكم من الله. إن الله كان عليماً بخلقه، حكيماً فيما شرعه لهم."},{"id":"505","jozz":"4","page":"79","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"11","aya_no":"12","aya_text":"۞ وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ إِن لَّمۡ يَكُن لَّهُنَّ وَلَدٞۚ فَإِن كَانَ لَهُنَّ وَلَدٞ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِينَ بِهَآ أَوۡ دَيۡنٖۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ يَكُن لَّكُمۡ وَلَدٞۚ فَإِن كَانَ لَكُمۡ وَلَدٞ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ مِّنۢ بَعۡدِ وَصِيَّةٖ تُوصُونَ بِهَآ أَوۡ دَيۡنٖۗ وَإِن كَانَ رَجُلٞ يُورَثُ كَلَٰلَةً أَوِ ٱمۡرَأَةٞ وَلَهُۥٓ أَخٌ أَوۡ أُخۡتٞ فَلِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوٓاْ أَكۡثَرَ مِن ذَٰلِكَ فَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصَىٰ بِهَآ أَوۡ دَيۡنٍ غَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ","aya_text_emlaey":"ولكم نصف ما ترك أزواجكم إن لم يكن لهن ولد فإن كان لهن ولد فلكم الربع مما تركن من بعد وصية يوصين بها أو دين ولهن الربع مما تركتم إن لم يكن لكم ولد فإن كان لكم ولد فلهن الثمن مما تركتم من بعد وصية توصون بها أو دين وإن كان رجل يورث كلالة أو امرأة وله أخ أو أخت فلكل واحد منهما السدس فإن كانوا أكثر من ذلك فهم شركاء في الثلث من بعد وصية يوصى بها أو دين غير مضار وصية من الله والله عليم حليم","aya_tafseer":"[12] ولكم -أيها الرجال- نصف ما ترك أزواجكم بعد وفاتهن إن لم يكن لهن ولد، ذكراً كان أو أنثى، فإن كان لهن ولد فلكم الربع مما تركن، ترثونه من بعدِ إنفاذ وصيتهن الجائزة، أو ما يكون عليهن مِن دَيْن لمستحقيه. ولأزواجكم -أيها الرجال- الربع مما تركتم، إن لم يكن لكم ابن أو ابنة منهن أو من غيرهن، فإن كان لكم ابن أو ابنة فلهن الثمن مما تركتم، يقسم الربع أو الثمن بينهن، فإن كانت زوجة واحدة كان هذا ميراثاً لها، من بعد إنفاذ ما كنتم أوصيتم به من الوصايا الجائزة، أو قضاء ما يكون عليكم من دَيْن. وإن مات رجل أو امرأة وليس له أو لها ولد ولا والد، وله أو لها أخ أو أخت من أم فلكل واحد منهما السدس. فإن كان الإخوة أو الأخوات لأم أكثر من ذلك فهم شركاء في الثلث يقسم بينهم بالسوية لا فرق بين الذكر والأنثى، وهذا الذي فرضه الله للإخوة والأخوات لأم يأخذونه ميراثاً لهم، من بعد إنفاذ وصيته إن كان قد أوصى بشيء، أو قضاء ديون الميت، لا ضرر فيه على الورثة. بهذا أوصاكم ربكم وصية نافعة لكم. والله عليم بما يصلح خلقه، حليم لا يعاجلهم بالعقوبة."},{"id":"506","jozz":"4","page":"79","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"11","line_end":"13","aya_no":"13","aya_text":"تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","aya_text_emlaey":"تلك حدود الله ومن يطع الله ورسوله يدخله جنات تجري من تحتها الأنهار خالدين فيها وذلك الفوز العظيم","aya_tafseer":"[13] تلك الأحكام الإلهية التي شرعها الله في اليتامى والنساء والمواريث، شرائعه الدالة على أنها مِن عند الله العليم الحكيم. ومَن يطع الله ورسوله فيما شرع لعباده من هذه الأحكام وغيرها، يدخله جنات كثيرة الأشجار والقصور، تجري من تحتها الأنهار بمياهها العذبة، وهم باقون في هذا النعيم، لا يخرجون منه، وذلك الثواب هو الفلاح العظيم."},{"id":"507","jozz":"4","page":"79","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"14","line_end":"15","aya_no":"14","aya_text":"وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ نَارًا خَٰلِدٗا فِيهَا وَلَهُۥ عَذَابٞ مُّهِينٞ","aya_text_emlaey":"ومن يعص الله ورسوله ويتعد حدوده يدخله نارا خالدا فيها وله عذاب مهين","aya_tafseer":"[14] ومَن يَعْصِ الله ورسوله، بإنكاره لأحكام الله، وتجاوزه ما شرعه الله لعباده بتغييرها، أو تعطيل العمل بها، يدخله ناراً ماكثاً فيها، وله عذاب يُخزيه ويُهينه."},{"id":"508","jozz":"4","page":"80","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"3","aya_no":"15","aya_text":"وَٱلَّٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ فَٱسۡتَشۡهِدُواْ عَلَيۡهِنَّ أَرۡبَعَةٗ مِّنكُمۡۖ فَإِن شَهِدُواْ فَأَمۡسِكُوهُنَّ فِي ٱلۡبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلٗا","aya_text_emlaey":"واللاتي يأتين الفاحشة من نسائكم فاستشهدوا عليهن أربعة منكم فإن شهدوا فأمسكوهن في البيوت حتى يتوفاهن الموت أو يجعل الله لهن سبيلا","aya_tafseer":"[15] واللاتي يزنين من نسائكم، فاستشهدوا -أيها الولاة والقضاة- عليهن أربعة رجال عدول من المسلمين، فإن شهدوا عليهن بذلك فاحبسوهن في البيوت حتى تنتهي حياتهن بالموت، أو يجعل الله لهن طريقاً للخلاص من ذلك."},{"id":"509","jozz":"4","page":"80","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"5","aya_no":"16","aya_text":"وَٱلَّذَانِ يَأۡتِيَٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا وَأَصۡلَحَا فَأَعۡرِضُواْ عَنۡهُمَآۗ إِنَّ ٱللَّهَ كَانَ تَوَّابٗا رَّحِيمًا","aya_text_emlaey":"واللذان يأتيانها منكم فآذوهما فإن تابا وأصلحا فأعرضوا عنهما إن الله كان توابا رحيما","aya_tafseer":"[16] واللذان يقعان في فاحشة الزنى، فآذُوهما بالضرب والهجر والتوبيخ، فإن تابا عَمَّا وقع منهما وأصلحا بما يقدِّمان من الأعمال الصالحة فاصفحوا عن أذاهما. ويستفاد من هذه الآية والتي قبلها أن الرجال إذا فعلوا الفاحشة يُؤذَوْن، والنساء يُحْبَسْنَ ويُؤذَيْنَ، فالحبس غايته الموت، والأذية نهايتها إلى التوبة والصلاح. وكان هذا في صدر الإسلام، ثم نُسخ بما شرع الله ورسوله، وهو الرجم للمحصن والمحصنة، وهما الحران البالغان العاقلان، اللذان جامعا في نكاح صحيح، والجلدُ مائة جلدة، وتغريب عام لغيرهما. إن الله كان تواباً على عباده التائبين، رحيماً بهم."},{"id":"510","jozz":"4","page":"80","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"8","aya_no":"17","aya_text":"إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ يَتُوبُونَ مِن قَرِيبٖ فَأُوْلَٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيۡهِمۡۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","aya_text_emlaey":"إنما التوبة على الله للذين يعملون السوء بجهالة ثم يتوبون من قريب فأولئك يتوب الله عليهم وكان الله عليما حكيما","aya_tafseer":"[17] إنَّما يقبل الله التوبة من الذين يرتكبون المعاصي والذنوب بجهل منهم لعاقبتها، وإيجابها لسخط الله، وبغفلة منهم أو ضعف يقين -فكل عاص لله، مخطئاً أو متعمِّداً، فهو جاهل بهذا الاعتبار، وإن كان عالماً بالتحريم- ثم يرجعون إلى ربهم بالإنابة والطاعة قبل معاينة الموت، فأولئك يقبل الله توبتهم. وكان الله عليماً بخلقه، حكيماً في تدبيره وتقديره."},{"id":"511","jozz":"4","page":"80","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"11","aya_no":"18","aya_text":"وَلَيۡسَتِ ٱلتَّوۡبَةُ لِلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ إِنِّي تُبۡتُ ٱلۡـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمۡ كُفَّارٌۚ أُوْلَٰٓئِكَ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا","aya_text_emlaey":"وليست التوبة للذين يعملون السيئات حتى إذا حضر أحدهم الموت قال إني تبت الآن ولا الذين يموتون وهم كفار أولئك أعتدنا لهم عذابا أليما","aya_tafseer":"[18] وليس قَبول التوبة للذين يُصِرُّون على ارتكاب المعاصي، ولا يرجعون إلى ربهم إلى أن تأتيهم سكرات الموت، فيقول أحدهم: إني تبت الآن، كما لا تُقبل توبة الذين يموتون وهم جاحدون، منكرون لوحدانية الله ورسالة رسوله محمد -صلى الله عليه وسلم-. أولئك المصرُّون على المعاصي إلى أن ماتوا، والجاحدون الذين يموتون وهم كفار، أعتدنا لهم عذاباً موجعاً."},{"id":"512","jozz":"4","page":"80","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"11","line_end":"15","aya_no":"19","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَحِلُّ لَكُمۡ أَن تَرِثُواْ ٱلنِّسَآءَ كَرۡهٗاۖ وَلَا تَعۡضُلُوهُنَّ لِتَذۡهَبُواْ بِبَعۡضِ مَآ ءَاتَيۡتُمُوهُنَّ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا","aya_text_emlaey":"ياأيها الذين آمنوا لا يحل لكم أن ترثوا النساء كرها ولا تعضلوهن لتذهبوا ببعض ما آتيتموهن إلا أن يأتين بفاحشة مبينة وعاشروهن بالمعروف فإن كرهتموهن فعسى أن تكرهوا شيئا ويجعل الله فيه خيرا كثيرا","aya_tafseer":"[19] يا أيها الذين آمنوا لا يجوز لكم أن تجعلوا نساء آبائكم من جملة تَرِكتهم، تتصرفون فيهن بالزواج منهن، أو المنع لهن، أو تزويجهن للآخرين، وهن كارهات لذلك كله، ولا يجوز لكم أن تضارُّوا أزواجكم وأنتم كارهون لهن؛ ليتنازلن عن بعض ما آتيتموهن مِن مهر ونحوه، إلا أن يرتكبن أمراً فاحشاً كالزنى، فلكم حينئذ إمساكهن حتى تأخذوا ما أعطيتموهن. ولتكن مصاحبتكم لنسائكم مبنية على التكريم والمحبة، وأداء ما لهن من حقوق. فإن كرهتموهن لسبب من الأسباب الدنيوية فاصبروا؛ فعسى أن تكرهوا أمراً من الأمور ويكون فيه خير كثير."},{"id":"513","jozz":"4","page":"81","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"3","aya_no":"20","aya_text":"وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ وَءَاتَيۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارٗا فَلَا تَأۡخُذُواْ مِنۡهُ شَيۡـًٔاۚ أَتَأۡخُذُونَهُۥ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا","aya_text_emlaey":"وإن أردتم استبدال زوج مكان زوج وآتيتم إحداهن قنطارا فلا تأخذوا منه شيئا أتأخذونه بهتانا وإثما مبينا","aya_tafseer":"[20] وإن أردتم استبدال زوجة مكان أخرى، وكنتم قد أعطيتم مَن تريدون طلاقها مالاً كثيراً مهراً لها، فلا يحلُّ لكم أن تأخذوا منه شيئاً، أتأخذونه كذباً وافتراءً واضحاً؟"},{"id":"514","jozz":"4","page":"81","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"4","aya_no":"21","aya_text":"وَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضٖ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا غَلِيظٗا","aya_text_emlaey":"وكيف تأخذونه وقد أفضى بعضكم إلى بعض وأخذن منكم ميثاقا غليظا","aya_tafseer":"[21] وكيف يحلُّ لكم أن تأخذوا ما أعطيتموهن من مهر، وقد استمتع كل منكما بالآخر بالجماع، وأَخَذْنَ منكم ميثاقاً غليظاً من إمساكهن بمعروف أو تسريحهن بإحسان؟"},{"id":"515","jozz":"4","page":"81","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"5","line_end":"7","aya_no":"22","aya_text":"وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَمَقۡتٗا وَسَآءَ سَبِيلًا","aya_text_emlaey":"ولا تنكحوا ما نكح آباؤكم من النساء إلا ما قد سلف إنه كان فاحشة ومقتا وساء سبيلا","aya_tafseer":"[22] ولا تتزوجوا مَن تزوجه آباؤكم من النساء إلَّا ما قد مضى منكم في الجاهلية فلا مؤاخذة فيه. إن زواج الأبناء من زوجات آبائهم أمر قبيح يفحش ويعظم قبحه، وبغيض يمقت الله فاعله، وبئس طريقاً ومنهجاً ما كنتم تفعلونه في جاهليتكم."},{"id":"516","jozz":"4","page":"81","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"15","aya_no":"23","aya_text":"حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَٰتُكُمۡ وَعَمَّٰتُكُمۡ وَخَٰلَٰتُكُمۡ وَبَنَاتُ ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَٰتُكُمُ ٱلَّٰتِيٓ أَرۡضَعۡنَكُمۡ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمۡ وَرَبَٰٓئِبُكُمُ ٱلَّٰتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّٰتِي دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُواْ دَخَلۡتُم بِهِنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ وَحَلَٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ مِنۡ أَصۡلَٰبِكُمۡ وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا","aya_text_emlaey":"حرمت عليكم أمهاتكم وبناتكم وأخواتكم وعماتكم وخالاتكم وبنات الأخ وبنات الأخت وأمهاتكم اللاتي أرضعنكم وأخواتكم من الرضاعة وأمهات نسائكم وربائبكم اللاتي في حجوركم من نسائكم اللاتي دخلتم بهن فإن لم تكونوا دخلتم بهن فلا جناح عليكم وحلائل أبنائكم الذين من أصلابكم وأن تجمعوا بين الأختين إلا ما قد سلف إن الله كان غفورا رحيما","aya_tafseer":"[23] حَرَّمَ الله عليكم نكاح أمهاتكم، ويدخل في ذلك الجدَّات مِن جهة الأب أو الأم، وبناتِكم: ويشمل بنات الأولاد وإن نزلن، وأخواتِكم الشقيقات أو لأب أو لأم، وعماتِكم: أخوات آبائكم وأجدادكم، وخالاتِكم: أخوات أمهاتكم وجداتِكم، وبناتِ الأخ، وبناتِ الأخت: ويدخل في ذلك أولادهن، وأمهاتِكم اللاتي أرضعنكم، وأخواتِكم من الرضاعة -وقد حرَّم رسول الله -صلى الله عليه وسلم- من الرَّضاع ما يحرم من النسب- وأمهاتِ نسائكم، سواء دخلتم بنسائكم، أم لم تدخلوا بهن، وبناتِ نسائكم من غيركم اللاتي يتربَّيْنَ غالباً في بيوتكم وتحت رعايتكم، وهن مُحَرَّمات وإن لم يكنَّ في حجوركم، ولكن بشرط الدخول بأمهاتهن، فإن لم تكونوا دخلتم بأمهاتهن وطلقتموهن أو متْنَ قبل الدخول فلا جناح عليكم أن تنكحوهن، كما حَرَّم الله عليكم أن تنكحوا زوجات أبنائكم الذين من أصلابكم، ومن أُلحق بهم مِن أبنائكم مِن الرَّضاع، وهذا التحريم يكون بالعقد عليها، دخل الابن بها أم لم يدخل، وحَرَّم عليكم كذلك الجمعَ في وقت واحد بين الأختين بنسب أو رَضاع إلَّا ما قد مضى منكم في الجاهلية. ولا يجوز كذلك الجمعُ بين المرأة وعمتها أو خالتها كما جاء في السنة. إن الله كان غفوراً للمذنبين إذا تابوا، رحيماً بهم، فلا يكلفهم ما لا يطيقون."},{"id":"517","jozz":"5","page":"82","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"6","aya_no":"24","aya_text":"۞ وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ أَن تَبۡتَغُواْ بِأَمۡوَٰلِكُم مُّحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا","aya_text_emlaey":"والمحصنات من النساء إلا ما ملكت أيمانكم كتاب الله عليكم وأحل لكم ما وراء ذلكم أن تبتغوا بأموالكم محصنين غير مسافحين فما استمتعتم به منهن فآتوهن أجورهن فريضة ولا جناح عليكم فيما تراضيتم به من بعد الفريضة إن الله كان عليما حكيما","aya_tafseer":"[24] ويحرم عليكم نكاح المتزوجات من النساء، إلا مَن سَبَيْتم منهن في الجهاد، فإنه يحل لكم نكاحهن، بعد استبراء أرحامهن بحيضة، كتب الله عليكم تحريم نكاح هؤلاء، وأجاز لكم نكاح مَن سواهن، ممَّا أحلَّه الله لكم أن تطلبوا بأموالكم العفة عن اقتراف الحرام. فما استمتعتم به منهن بالنكاح الصحيح، فأعطوهن مهورهن، التي فرض الله لهن عليكم، ولا إثم عليكم فيما تمَّ التراضي به بينكم، من الزيادة أو النقصان في المهر، بعد ثبوت الفريضة. إن الله تعالى كان عليماً بأمور عباده، حكيماً في أحكامه وتدبيره."},{"id":"518","jozz":"5","page":"82","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"13","aya_no":"25","aya_text":"وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضٖۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلۡمَعۡرُوفِ مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتٖ وَلَا مُتَّخِذَٰتِ أَخۡدَانٖۚ فَإِذَآ أُحۡصِنَّ فَإِنۡ أَتَيۡنَ بِفَٰحِشَةٖ فَعَلَيۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"ومن لم يستطع منكم طولا أن ينكح المحصنات المؤمنات فمن ما ملكت أيمانكم من فتياتكم المؤمنات والله أعلم بإيمانكم بعضكم من بعض فانكحوهن بإذن أهلهن وآتوهن أجورهن بالمعروف محصنات غير مسافحات ولا متخذات أخدان فإذا أحصن فإن أتين بفاحشة فعليهن نصف ما على المحصنات من العذاب ذلك لمن خشي العنت منكم وأن تصبروا خير لكم والله غفور رحيم","aya_tafseer":"[25] ومن لا قدرة له على مهور الحرائر المؤمنات، فله أن ينكح غيرهن، من فتياتكم المؤمنات المملوكات. والله تعالى هو العليم بحقيقة إيمانكم، بعضكم من بعض، فكلُّكم من نفس واحدة، وإخوةٌ في الدين، فتزوجوهن بموافقة أهلهن، وأعطوهن مهورهن على ما تراضيتم به عن طيب نفس منكم، متعففات عن الحرام، غير مجاهرات بالزنى، ولا مسرات به باتخاذ أخلاء، فإذا تزوجن وأتين بفاحشة الزنى فعليهن من الحدِّ -وهو الجَلْدُ لا الرَّجْمُ- نصفُ ما على الحرائر. ذلك الذي أبيح مِن نكاح الإماء بالصفة المتقدِّمة إنما أبيح لمن خاف على نفسه الوقوع في الزنى، وشق عليه الصبر عن الجماع، والصبر عن نكاح الإماء مع العفة أولى وأفضل. والله تعالى غفور لكم، رحيم بكم إذ أذن لكم في نكاحهن عند العجز عن نكاح الحرائر."},{"id":"519","jozz":"5","page":"82","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"14","line_end":"15","aya_no":"26","aya_text":"يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ وَيَتُوبَ عَلَيۡكُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","aya_text_emlaey":"يريد الله ليبين لكم ويهديكم سنن الذين من قبلكم ويتوب عليكم والله عليم حكيم","aya_tafseer":"[26] يريد الله تعالى بهذه التشريعات، أن يوضح لكم معالم دينه القويم، وشرعه الحكيم، ويدلَّكم على طرق الأنبياء والصالحين من قبلكم في الحلال والحرام، ويتوب عليكم بالرجوع بكم إلى الطاعات، وهو سبحانه عليم بما يصلح شأن عباده، حكيم فيما شرعه لكم."},{"id":"520","jozz":"5","page":"83","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"2","aya_no":"27","aya_text":"وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُواْ مَيۡلًا عَظِيمٗا","aya_text_emlaey":"والله يريد أن يتوب عليكم ويريد الذين يتبعون الشهوات أن تميلوا ميلا عظيما","aya_tafseer":"[27] والله يريد أن يتوب عليكم، ويتجاوز عن خطاياكم، ويريد الذين ينقادون لشهواتهم وملذاتهم أن تنحرفوا عن الدين انحرافاً كبيراً."},{"id":"521","jozz":"5","page":"83","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"2","line_end":"3","aya_no":"28","aya_text":"يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَٰنُ ضَعِيفٗا","aya_text_emlaey":"يريد الله أن يخفف عنكم وخلق الإنسان ضعيفا","aya_tafseer":"[28] يريد الله تعالى بما شرعه لكم التيسير، وعدم التشديد عليكم؛ لأنكم خلقتم ضعفاء."},{"id":"522","jozz":"5","page":"83","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"6","aya_no":"29","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا","aya_text_emlaey":"ياأيها الذين آمنوا لا تأكلوا أموالكم بينكم بالباطل إلا أن تكون تجارة عن تراض منكم ولا تقتلوا أنفسكم إن الله كان بكم رحيما","aya_tafseer":"[29] يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه، لا يحلُّ لكم أن يأكل بعضكم مال بعض بغير حق، إلا أن يكون وَفْقَ الشرع والكسب الحلال عن تراض منكم، ولا يقتل بعضكم بعضاً فتهلكوا أنفسكم بارتكاب محارم الله ومعاصيه. إن الله كان بكم رحيماً في كل ما أمركم به، ونهاكم عنه."},{"id":"523","jozz":"5","page":"83","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"8","aya_no":"30","aya_text":"وَمَن يَفۡعَلۡ ذَٰلِكَ عُدۡوَٰنٗا وَظُلۡمٗا فَسَوۡفَ نُصۡلِيهِ نَارٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا","aya_text_emlaey":"ومن يفعل ذلك عدوانا وظلما فسوف نصليه نارا وكان ذلك على الله يسيرا","aya_tafseer":"[30] ومن يرتكب ما نهى الله عنه من أَخْذ المال الحرام كالسرقة والغَصْب والغِشِّ معتدياً متجاوزاً حد الشرع، فسوف يدخله الله ناراً يقاسي حرَّها، وكان ذلك على الله يسيراً."},{"id":"524","jozz":"5","page":"83","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"9","aya_no":"31","aya_text":"إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلٗا كَرِيمٗا","aya_text_emlaey":"إن تجتنبوا كبائر ما تنهون عنه نكفر عنكم سيئاتكم وندخلكم مدخلا كريما","aya_tafseer":"[31] إن تبتعدوا -أيها المؤمنون- عن كبائر الذنوب كالإشراك بالله وعقوق الوالدين وقَتْلِ النفس بغير الحق وغير ذلك، نكفِّر عنكم ما دونها من الصغائر، وندخلكم مدخلاً كريماً، وهو الجنّة."},{"id":"525","jozz":"5","page":"83","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"13","aya_no":"32","aya_text":"وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ لِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا","aya_text_emlaey":"ولا تتمنوا ما فضل الله به بعضكم على بعض للرجال نصيب مما اكتسبوا وللنساء نصيب مما اكتسبن واسألوا الله من فضله إن الله كان بكل شيء عليما","aya_tafseer":"[32] ولا تتمنوا ما فضَّل الله به بعضكم على بعض، في المواهب والأرزاق وغير ذلك، فقد جعل الله للرجال نصيباً مقدَّراً من الجزاء بحسب عملهم، وجعل للنساء نصيباً مما عملن، واسألوا الله الكريم الوهاب يُعْطِكم مِن فضله بدلاً من التمني. إن الله كان بكل شيء عليماً، وهو أعلم بما يصلح عباده فيما قسمه لهم من خير."},{"id":"526","jozz":"5","page":"83","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"15","aya_no":"33","aya_text":"وَلِكُلّٖ جَعَلۡنَا مَوَٰلِيَ مِمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ فَـَٔاتُوهُمۡ نَصِيبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا","aya_text_emlaey":"ولكل جعلنا موالي مما ترك الوالدان والأقربون والذين عقدت أيمانكم فآتوهم نصيبهم إن الله كان على كل شيء شهيدا","aya_tafseer":"[33] ولكل واحد منكم جعلنا ورثة يرثون مما ترك الوالدان والأقربون، والذين تحالفتم معهم بالأيمان المؤكدة على النصرة وإعطائهم شيئاً من الميراث فأعطوهم ما قُدِّر لهم. والميراث بالتحالف كان في أول الإسلام، ثم رُفع حكمه بنزول آيات المواريث. إن الله كان مُطَّلِعاً على كل شيء من أعمالكم، وسيجازيكم على ذلك."},{"id":"527","jozz":"5","page":"84","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"6","aya_no":"34","aya_text":"ٱلرِّجَالُ قَوَّٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضٖ وَبِمَآ أَنفَقُواْ مِنۡ أَمۡوَٰلِهِمۡۚ فَٱلصَّٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّٰتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا","aya_text_emlaey":"الرجال قوامون على النساء بما فضل الله بعضهم على بعض وبما أنفقوا من أموالهم فالصالحات قانتات حافظات للغيب بما حفظ الله واللاتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فإن أطعنكم فلا تبغوا عليهن سبيلا إن الله كان عليا كبيرا","aya_tafseer":"[34] الرجال قوَّامون على توجيه النساء ورعايتهن، بما خصهم الله به من خصائص القِوامَة والتفضيل، وبما أعطَوْهن من المهور والنفقات. فالصالحات المستقيمات على شرع الله منهن، مطيعات لله تعالى ولأزواجهن، حافظات لكل ما غاب عن علم أزواجهن بما اؤتمنَّ عليه بحفظ الله وتوفيقه، واللاتي تخشون منهن ترفُّعهن عن طاعتكم، فانصحوهن بالكلمة الطيبة، فإن لم تثمر معهن الكلمة الطيبة، فاهجروهن في الفراش، ولا تقربوهن، فإن لم يؤثر فعل الهِجْران فيهن، فاضربوهن ضرباً لا ضرر فيه، فإن أطعنكم فاحذروا ظلمهن، فإن الله العليَّ الكبير وليُّهن، وهو منتقم ممَّن ظلمهنَّ وبغى عليهن."},{"id":"528","jozz":"5","page":"84","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"9","aya_no":"35","aya_text":"وَإِنۡ خِفۡتُمۡ شِقَاقَ بَيۡنِهِمَا فَٱبۡعَثُواْ حَكَمٗا مِّنۡ أَهۡلِهِۦ وَحَكَمٗا مِّنۡ أَهۡلِهَآ إِن يُرِيدَآ إِصۡلَٰحٗا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرٗا","aya_text_emlaey":"وإن خفتم شقاق بينهما فابعثوا حكما من أهله وحكما من أهلها إن يريدا إصلاحا يوفق الله بينهما إن الله كان عليما خبيرا","aya_tafseer":"[35] وإن علمتم -يا أولياء الزوجين- شقاقاً بينهما يؤدي إلى الفراق، فأرسلوا إليهما حكماً عدلاً من أهل الزوج، وحكماً عدلاً من أهل الزوجة؛ لينظرا ويحكما بما فيه المصلحة لهما، وبسبب رغبة الحكمين في الإصلاح، واستعمالهما الأسلوب الطيب يوفق الله بين الزوجين. إن الله تعالى عليم، لا يخفى عليه شيء من أمر عباده، خبير بما تنطوي عليه نفوسهم."},{"id":"529","jozz":"5","page":"84","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"13","aya_no":"36","aya_text":"۞ وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا","aya_text_emlaey":"واعبدوا الله ولا تشركوا به شيئا وبالوالدين إحسانا وبذي القربى واليتامى والمساكين والجار ذي القربى والجار الجنب والصاحب بالجنب وابن السبيل وما ملكت أيمانكم إن الله لا يحب من كان مختالا فخورا","aya_tafseer":"[36] واعبدوا الله وانقادوا له وحده، ولا تجعلوا له شريكاً في الربوبية والعبادة، وأحسنوا إلى الوالدين، وأدُّوا حقوقهما، وحقوق الأقربين، والأولاد الذين مات آباؤهم وهم دون سن البلوغ، والمحتاجين الذين لا يملكون ما يكفيهم ويسدُّ حاجتهم، والجار القريب منكم والبعيد، والرفيق في السفر وفي الحضر، والمسافر المحتاج، والمماليك من فتيانكم وفتياتكم. إن الله تعالى لا يحب المتكبرين من عباده، المفتخرين على الناس."},{"id":"530","jozz":"5","page":"84","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"15","aya_no":"37","aya_text":"ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ وَيَكۡتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا","aya_text_emlaey":"الذين يبخلون ويأمرون الناس بالبخل ويكتمون ما آتاهم الله من فضله وأعتدنا للكافرين عذابا مهينا","aya_tafseer":"[37] الذين يمتنعون عن الإنفاق والعطاء مما رزقهم الله، ويأمرون غيرهم بالبخل، ويجحدون نِعَمَ الله عليهم، ويخفون فضله وعطاءه. وأعددنا للجاحدين عذاباً مخزياً."},{"id":"531","jozz":"5","page":"85","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"3","aya_no":"38","aya_text":"وَٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِۗ وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا فَسَآءَ قَرِينٗا","aya_text_emlaey":"والذين ينفقون أموالهم رئاء الناس ولا يؤمنون بالله ولا باليوم الآخر ومن يكن الشيطان له قرينا فساء قرينا","aya_tafseer":"[38] وأعتدنا هذا العذاب كذلك للذين ينفقون أموالهم رياءً وسمعةً، ولا يصدقون بالله اعتقاداً وعملاً ولا بيوم القيامة. وهذه الأعمال السيئة مما يدعو إليها الشيطان. ومن يكن الشيطان له ملازماً فبئس الملازم والقرين."},{"id":"532","jozz":"5","page":"85","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"4","aya_no":"39","aya_text":"وَمَاذَا عَلَيۡهِمۡ لَوۡ ءَامَنُواْ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَنفَقُواْ مِمَّا رَزَقَهُمُ ٱللَّهُۚ وَكَانَ ٱللَّهُ بِهِمۡ عَلِيمًا","aya_text_emlaey":"وماذا عليهم لو آمنوا بالله واليوم الآخر وأنفقوا مما رزقهم الله وكان الله بهم عليما","aya_tafseer":"[39] وأيُّ ضرر يلحقهم لو صدَّقوا بالله واليوم الآخر اعتقاداً وعملاً، وأنفقوا مما أعطاهم الله باحتساب وإخلاص، والله تعالى عليم بهم وبما يعملون، وسيحاسبهم على ذلك."},{"id":"533","jozz":"5","page":"85","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"6","aya_no":"40","aya_text":"إِنَّ ٱللَّهَ لَا يَظۡلِمُ مِثۡقَالَ ذَرَّةٖۖ وَإِن تَكُ حَسَنَةٗ يُضَٰعِفۡهَا وَيُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِيمٗا","aya_text_emlaey":"إن الله لا يظلم مثقال ذرة وإن تك حسنة يضاعفها ويؤت من لدنه أجرا عظيما","aya_tafseer":"[40] إن الله تعالى لا ينقص أحداً مِن جزاء عمله مقدار ذرة، وإن تكن زنة الذرة حسنة فإنه سبحانه يزيدها ويكثرها لصاحبها، ويتفضل عليه بالمزيد، فيعطيه من عنده ثواباً كبيراً هو الجنة."},{"id":"534","jozz":"5","page":"85","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"7","aya_no":"41","aya_text":"فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدٖ وَجِئۡنَا بِكَ عَلَىٰ هَٰٓؤُلَآءِ شَهِيدٗا","aya_text_emlaey":"فكيف إذا جئنا من كل أمة بشهيد وجئنا بك على هؤلاء شهيدا","aya_tafseer":"[41] فكيف يكون حال الناس يوم القيامة، إذا جاء الله من كل أمة برسولها ليشهد عليها بما عملت، وجاء بك -أيها الرسول- لتكون شهيداً على أمتك أنك بلَّغتهم رسالة ربِّك؟"},{"id":"535","jozz":"5","page":"85","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"9","aya_no":"42","aya_text":"يَوۡمَئِذٖ يَوَدُّ ٱلَّذِينَ كَفَرُواْ وَعَصَوُاْ ٱلرَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ وَلَا يَكۡتُمُونَ ٱللَّهَ حَدِيثٗا","aya_text_emlaey":"يومئذ يود الذين كفروا وعصوا الرسول لو تسوى بهم الأرض ولا يكتمون الله حديثا","aya_tafseer":"[42] يوم يكون ذلك، يتمنى الذين كفروا بالله تعالى وخالفوا الرسول ولم يطيعوه، لو يجعلهم الله والأرضَ سواء، فيصيرون تراباً، حتى لا يبعثوا وهم لا يستطيعون أن يُخفوا عن الله شيئاً مما في أنفسهم؛ إذ ختم الله على أفواههم، وشَهِدَتْ عليهم جوارحهم بما كانوا يعملون."},{"id":"536","jozz":"5","page":"85","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"14","aya_no":"43","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ حَتَّىٰ تَغۡتَسِلُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا","aya_text_emlaey":"ياأيها الذين آمنوا لا تقربوا الصلاة وأنتم سكارى حتى تعلموا ما تقولون ولا جنبا إلا عابري سبيل حتى تغتسلوا وإن كنتم مرضى أو على سفر أو جاء أحد منكم من الغائط أو لامستم النساء فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا بوجوهكم وأيديكم إن الله كان عفوا غفورا","aya_tafseer":"[43] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا تقربوا الصلاة ولا تقوموا إليها حال السكر حتى تميزوا وتعلموا ما تقولون (وقد كان هذا قبل التحريم القاطع للخمر في كل حال)، ولا تقربوا الصلاة إن أصابكم الحدث الأكبر، ولا تقربوا كذلك مواضعها وهي المساجد، إلا من كان منكم مجتازاً من باب إلى باب، حتى تتطهروا بالاغتسال. وإن كنتم في حال مرض لا تقدرون معه على استعمال الماء، أو حال سفر، أو جاء أحد منكم من الغائط، أو جامعتم النساء، فلم تجدوا ماء للطهارة فاقصدوا تراباً طاهراً، فامسحوا بوجوهكم وأيديكم منه. إن الله تعالى كان كثيرَ العفو يتجاوز عن سيئاتكم، ويسترها عليكم."},{"id":"537","jozz":"5","page":"85","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"14","line_end":"15","aya_no":"44","aya_text":"أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يَشۡتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّواْ ٱلسَّبِيلَ","aya_text_emlaey":"ألم تر إلى الذين أوتوا نصيبا من الكتاب يشترون الضلالة ويريدون أن تضلوا السبيل","aya_tafseer":"[44] ألم تعلم -أيها الرسول- أمر اليهود الذين أُعطوا حظّاً من العلم مما جاءهم من التوراة، يستبدلون الضلالة بالهدى، ويتركون ما لديهم من الحجج والبراهين، الدالة على صدق رسالة الرسول محمد -صلى الله عليه وسلم-، ويتمنون لكم -أيها المؤمنون المهتدون- أن تنحرفوا عن الطريق المستقيم؛ لتكونوا ضالين مثلهم."},{"id":"538","jozz":"5","page":"86","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"1","aya_no":"45","aya_text":"وَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِيّٗا وَكَفَىٰ بِٱللَّهِ نَصِيرٗا","aya_text_emlaey":"والله أعلم بأعدائكم وكفى بالله وليا وكفى بالله نصيرا","aya_tafseer":"[45] والله سبحانه وتعالى أعلم منكم -أيها المؤمنون- بعداوة هؤلاء اليهود لكم، وكفى بالله وليّاً يتولاكم، وكفى به نصيراً ينصركم على أعدائكم."},{"id":"539","jozz":"5","page":"86","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"2","line_end":"6","aya_no":"46","aya_text":"مِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعۡنَا وَعَصَيۡنَا وَٱسۡمَعۡ غَيۡرَ مُسۡمَعٖ وَرَٰعِنَا لَيَّۢا بِأَلۡسِنَتِهِمۡ وَطَعۡنٗا فِي ٱلدِّينِۚ وَلَوۡ أَنَّهُمۡ قَالُواْ سَمِعۡنَا وَأَطَعۡنَا وَٱسۡمَعۡ وَٱنظُرۡنَا لَكَانَ خَيۡرٗا لَّهُمۡ وَأَقۡوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا","aya_text_emlaey":"من الذين هادوا يحرفون الكلم عن مواضعه ويقولون سمعنا وعصينا واسمع غير مسمع وراعنا ليا بألسنتهم وطعنا في الدين ولو أنهم قالوا سمعنا وأطعنا واسمع وانظرنا لكان خيرا لهم وأقوم ولكن لعنهم الله بكفرهم فلا يؤمنون إلا قليلا","aya_tafseer":"[46] من اليهود فريق دأبوا على تبديل كلام الله وتغييره عمَّا هو عليه افتراءً على الله، ويقولون للرسول -صلى الله عليه وسلم-: سمعنا قولك وعصينا أمرك واسمع منَّا لا سمعت، ويقولون: راعنا سمعك أي: افهم عنا وأفهمنا، يلوون ألسنتهم بذلك، وهم يريدون الدعاء عليه بالرعونة حسب لغتهم، والطعنَ في دين الإسلام. ولو أنهم قالوا: سمعنا وأطعنا، بدل و«عصينا»، واسمع دون «غير مسمع»، وانظرنا بدل «راعنا» لكان ذلك خيراً لهم عند الله وأعدل قولاً، ولكن الله طردهم من رحمته؛ بسبب كفرهم وجحودهم نبوة محمد -صلى الله عليه وسلم-، فلا يصدِّقون بالحق إلَّا تصديقاً قليلاً لا ينفعهم."},{"id":"540","jozz":"5","page":"86","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"9","aya_no":"47","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ ءَامِنُواْ بِمَا نَزَّلۡنَا مُصَدِّقٗا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهٗا فَنَرُدَّهَا عَلَىٰٓ أَدۡبَارِهَآ أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّآ أَصۡحَٰبَ ٱلسَّبۡتِۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولًا","aya_text_emlaey":"ياأيها الذين أوتوا الكتاب آمنوا بما نـزلنا مصدقا لما معكم من قبل أن نطمس وجوها فنردها على أدبارها أو نلعنهم كما لعنا أصحاب السبت وكان أمر الله مفعولا","aya_tafseer":"[47] يا أهل الكتاب، صدِّقوا واعملوا بما نَزَّلنا من القرآن، مصدقاً لما معكم من الكتب من قبل أن نأخذكم بسوء صنيعكم، فنمحو الوجوه ونحوِّلَها قِبَلَ الظهور، أو نلعن هؤلاء المفسدين بمسخهم قردة وخنازير، كما لعنَّا اليهود مِن أصحاب السبت، الذين نُهوا عن الصيد فيه فلم ينتهوا، فغضب الله عليهم، وطردهم من رحمته، وكان أمر الله نافذاً في كل حال."},{"id":"541","jozz":"5","page":"86","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"10","aya_no":"48","aya_text":"إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا","aya_text_emlaey":"إن الله لا يغفر أن يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد افترى إثما عظيما","aya_tafseer":"[48] إن الله تعالى لا يغفر ولا يتجاوز عمَّن أشرك به أحداً من مخلوقاته، أو كفر بأي نوع من أنواع الكفر الأكبر، ويتجاوز ويعفو عَمَّا دون الشرك من الذنوب، لمن يشاء من عباده، ومن يشرك بالله غيره فقد اختلق ذنباً عظيماً."},{"id":"542","jozz":"5","page":"86","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"11","line_end":"12","aya_no":"49","aya_text":"أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ وَلَا يُظۡلَمُونَ فَتِيلًا","aya_text_emlaey":"ألم تر إلى الذين يزكون أنفسهم بل الله يزكي من يشاء ولا يظلمون فتيلا","aya_tafseer":"[49] ألم تعلم -أيها الرسول- أمر أولئك الذين يُثْنون على أنفسهم وأعمالهم، ويصفونها بالطهر والبعد عن السوء؟ بل الله تعالى وحده هو الذي يُثْني على مَن يشاء مِن عباده، لعلمه بحقيقة أعمالهم، ولا يُنقَصون من أعمالهم شيئاً مقدار الخيط الذي يكون في شق نَواة التمرة."},{"id":"543","jozz":"5","page":"86","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"13","aya_no":"50","aya_text":"ٱنظُرۡ كَيۡفَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَكَفَىٰ بِهِۦٓ إِثۡمٗا مُّبِينًا","aya_text_emlaey":"انظر كيف يفترون على الله الكذب وكفى به إثما مبينا","aya_tafseer":"[50] انظر إليهم -أيها الرسول- متعجباً من أمرهم، كيف يختلقون على الله الكذب، وهو المنزَّه عن كل ما لا يليق به؟ وكفى بهذا الاختلاق ذنباً كبيراً كاشفاً عن فساد معتقدهم."},{"id":"544","jozz":"5","page":"86","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"15","aya_no":"51","aya_text":"أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُواْ هَٰٓؤُلَآءِ أَهۡدَىٰ مِنَ ٱلَّذِينَ ءَامَنُواْ سَبِيلًا","aya_text_emlaey":"ألم تر إلى الذين أوتوا نصيبا من الكتاب يؤمنون بالجبت والطاغوت ويقولون للذين كفروا هؤلاء أهدى من الذين آمنوا سبيلا","aya_tafseer":"[51] ألم تعلم -أيها الرسول- أمر أولئك اليهود الذين أُعطوا حظّاً من العلم، يصدِّقون بكل ما يُعبد من دون الله من الأصنام وشياطين الإنس والجن، تصديقاً يحملهم على التحاكم إلى غير شرع الله، ويقولون للذين كفروا بالله تعالى وبرسوله محمد -صلى الله عليه وسلم-: هؤلاء الكافرون أَقْوَمُ وأَعْدَلُ طريقاً من أولئك الذين آمنوا؟"},{"id":"545","jozz":"5","page":"87","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"1","aya_no":"52","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُۖ وَمَن يَلۡعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا","aya_text_emlaey":"أولئك الذين لعنهم الله ومن يلعن الله فلن تجد له نصيرا","aya_tafseer":"[52] أولئك الذين كَثُرَ فسادهم وعمَّ ضلالهم، طردهم الله تعالى من رحمته، ومَن يطرده الله من رحمته فلن تجد له من ينصره، ويدفع عنه سوء العذاب."},{"id":"546","jozz":"5","page":"87","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"2","line_end":"2","aya_no":"53","aya_text":"أَمۡ لَهُمۡ نَصِيبٞ مِّنَ ٱلۡمُلۡكِ فَإِذٗا لَّا يُؤۡتُونَ ٱلنَّاسَ نَقِيرًا","aya_text_emlaey":"أم لهم نصيب من الملك فإذا لا يؤتون الناس نقيرا","aya_tafseer":"[53] بل أَلَهُمْ حظ من الملك، ولو أوتوه لما أَعْطَوْا أحداً منه شيئاً، ولو كان مقدار النُّقرة التي تكون في ظهر النَّواة؟"},{"id":"547","jozz":"5","page":"87","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"2","line_end":"4","aya_no":"54","aya_text":"أَمۡ يَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَيۡنَآ ءَالَ إِبۡرَٰهِيمَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَءَاتَيۡنَٰهُم مُّلۡكًا عَظِيمٗا","aya_text_emlaey":"أم يحسدون الناس على ما آتاهم الله من فضله فقد آتينا آل إبراهيم الكتاب والحكمة وآتيناهم ملكا عظيما","aya_tafseer":"[54] بل أيحسدون محمداً -صلى الله عليه وسلم- على ما أعطاه الله من نعمة النبوة والرسالة، ويحسدون أصحابه على نعمة التوفيق إلى الإيمان، والتصديق بالرسالة، واتباع الرسول، والتمكين في الأرض، ويتمنون زوال هذا الفضل عنهم؟ فقد أعطينا ذرية إبراهيم عليه السلام -من قَبْلُ- الكتب، التي أنزلها الله عليهم وما أوحي إليهم مما لم يكن كتاباً مقروءاً، وأعطيناهم مع ذلك ملكاً واسعاً."},{"id":"548","jozz":"5","page":"87","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"5","line_end":"5","aya_no":"55","aya_text":"فَمِنۡهُم مَّنۡ ءَامَنَ بِهِۦ وَمِنۡهُم مَّن صَدَّ عَنۡهُۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا","aya_text_emlaey":"فمنهم من آمن به ومنهم من صد عنه وكفى بجهنم سعيرا","aya_tafseer":"[55] فمِن هؤلاء الذين أوتوا حظّاً من العلم، مَن صدَّق برسالة محمد -صلى الله عليه وسلم-، وعمل بشرعه، ومنهم مَن أعرض ولم يستجب لدعوته، ومنع الناس من اتباعه. وحسبكم -أيها المكذبون- نار جهنم تسعَّر بكم."},{"id":"549","jozz":"5","page":"87","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"8","aya_no":"56","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا سَوۡفَ نُصۡلِيهِمۡ نَارٗا كُلَّمَا نَضِجَتۡ جُلُودُهُم بَدَّلۡنَٰهُمۡ جُلُودًا غَيۡرَهَا لِيَذُوقُواْ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمٗا","aya_text_emlaey":"إن الذين كفروا بآياتنا سوف نصليهم نارا كلما نضجت جلودهم بدلناهم جلودا غيرها ليذوقوا العذاب إن الله كان عزيزا حكيما","aya_tafseer":"[56] إن الذين جحدوا ما أنزل الله من آياته ووحي كتابه ودلائله وحججه، سوف ندخلهم ناراً يقاسون حرَّها، كلما احترقت جلودهم بَدَّلْناهم جلوداً أخرى؛ ليستمر عذابهم وألمهم. إن الله تعالى كان عزيزاً لا يمتنع عليه شيء، حكيماً في تدبيره وقضائه."},{"id":"550","jozz":"5","page":"87","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"10","aya_no":"57","aya_text":"وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَنُدۡخِلُهُمۡ ظِلّٗا ظَلِيلًا","aya_text_emlaey":"والذين آمنوا وعملوا الصالحات سندخلهم جنات تجري من تحتها الأنهار خالدين فيها أبدا لهم فيها أزواج مطهرة وندخلهم ظلا ظليلا","aya_tafseer":"[57] والذين اطمأنت قلوبهم بالإيمان بالله تعالى والتصديق برسالة رسوله محمد -صلى الله عليه وسلم-، واستقاموا على الطاعة، سندخلهم جنات تجري من تحت قصورها وأشجارها الأنهار، ينعمون فيها أبداً ولا يخرجون منها، ولهم فيها أزواج طهرها الله مِن كل أذى، وندخلهم ظلّاً كثيفاً ممتدّاً في الجنة."},{"id":"551","jozz":"5","page":"87","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"13","aya_no":"58","aya_text":"۞ إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا بَصِيرٗا","aya_text_emlaey":"إن الله يأمركم أن تؤدوا الأمانات إلى أهلها وإذا حكمتم بين الناس أن تحكموا بالعدل إن الله نعما يعظكم به إن الله كان سميعا بصيرا","aya_tafseer":"[58] إن الله تعالى يأمركم بأداء مختلف الأمانات، التي اؤتمنتم عليها إلى أصحابها، فلا تفرطوا فيها، ويأمركم بالقضاء بين الناس بالعدل والقسط، إذا قضيتم بينهم، ونِعْمَ ما يعظكم الله به ويهديكم إليه. إن الله تعالى كان سميعاً لأقوالكم، مُطَّلعاً على سائر أعمالكم، بصيراً بها."},{"id":"552","jozz":"5","page":"87","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"15","aya_no":"59","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلًا","aya_text_emlaey":"ياأيها الذين آمنوا أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم فإن تنازعتم في شيء فردوه إلى الله والرسول إن كنتم تؤمنون بالله واليوم الآخر ذلك خير وأحسن تأويلا","aya_tafseer":"[59] يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه، استجيبوا لأوامر الله تعالى ولا تعصوه، واستجيبوا للرسول -صلى الله عليه وسلم- فيما جاء به من الحق، وأطيعوا ولاة أمركم في غير معصية الله، فإن اختلفتم في شيء بينكم، فأرجعوا الحكم فيه إلى كتاب الله تعالى وسنة رسوله محمد -صلى الله عليه وسلم-، إن كنتم تؤمنون حق الإيمان بالله تعالى وبيوم الحساب. ذلك الردُّ إلى الكتاب والسنة خير لكم من التنازع والقول بالرأي، وأحسن عاقبة ومآلاً."},{"id":"553","jozz":"5","page":"88","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"4","aya_no":"60","aya_text":"أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يَزۡعُمُونَ أَنَّهُمۡ ءَامَنُواْ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓاْ إِلَى ٱلطَّٰغُوتِ وَقَدۡ أُمِرُوٓاْ أَن يَكۡفُرُواْ بِهِۦۖ وَيُرِيدُ ٱلشَّيۡطَٰنُ أَن يُضِلَّهُمۡ ضَلَٰلَۢا بَعِيدٗا","aya_text_emlaey":"ألم تر إلى الذين يزعمون أنهم آمنوا بما أنـزل إليك وما أنـزل من قبلك يريدون أن يتحاكموا إلى الطاغوت وقد أمروا أن يكفروا به ويريد الشيطان أن يضلهم ضلالا بعيدا","aya_tafseer":"[60] ألم تعلم -أيها الرسول- أمر أولئك المنافقين الذين يدَّعون الإيمان بما أُنزل إليك -وهو القرآن- وبما أُنزل إلى الرسل من قبلك، وهم يريدون أن يتحاكموا في فَصْل الخصومات بينهم إلى غير ما شرع الله من الباطل، وقد أُمروا أن يكفروا بالباطل؟ ويريد الشيطان أن يبعدهم عن طريق الحق بُعْداً شديداً. وفي هذه الآية دليل على أن الإيمان الصادق، يقتضي الانقياد لشرع الله، والحكم به في كل أمر من الأمور، فمن زعم أنه مؤمن واختار حكم الطاغوت على حكم الله، فهو كاذب في زعمه."},{"id":"554","jozz":"5","page":"88","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"6","aya_no":"61","aya_text":"وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيۡتَ ٱلۡمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودٗا","aya_text_emlaey":"وإذا قيل لهم تعالوا إلى ما أنـزل الله وإلى الرسول رأيت المنافقين يصدون عنك صدودا","aya_tafseer":"[61] وإذا نُصح هؤلاء، وقيل لهم: تعالوا إلى ما أنزل الله، وإلى الرسول محمد -صلى الله عليه وسلم-، وهديه، أبصَرْتَ الذين يظهرون الإيمان ويبطنون الكفر، يعرضون عنك إعراضاً."},{"id":"555","jozz":"5","page":"88","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"8","aya_no":"62","aya_text":"فَكَيۡفَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ ثُمَّ جَآءُوكَ يَحۡلِفُونَ بِٱللَّهِ إِنۡ أَرَدۡنَآ إِلَّآ إِحۡسَٰنٗا وَتَوۡفِيقًا","aya_text_emlaey":"فكيف إذا أصابتهم مصيبة بما قدمت أيديهم ثم جاءوك يحلفون بالله إن أردنا إلا إحسانا وتوفيقا","aya_tafseer":"[62] فكيف يكون حال أولئك المنافقين إذا حلَّتْ بهم مصيبة؛ بسبب ما اقترفوه بأيديهم، ثم جاؤوك -أيها الرسول- يعتذرون، ويؤكدون لك أنهم ما قصدوا بأعمالهم تلك إلا الإحسان والتوفيق بين الخصوم؟"},{"id":"556","jozz":"5","page":"88","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"10","aya_no":"63","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ يَعۡلَمُ ٱللَّهُ مَا فِي قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ فِيٓ أَنفُسِهِمۡ قَوۡلَۢا بَلِيغٗا","aya_text_emlaey":"أولئك الذين يعلم الله ما في قلوبهم فأعرض عنهم وعظهم وقل لهم في أنفسهم قولا بليغا","aya_tafseer":"[63] أولئك هم الذين يعلم الله حقيقة ما في قلوبهم من النفاق، فتولَّ عنهم، وحذِّرهم من سوء ما هم عليه، وقل لهم قولاً مؤثراً فيهم زاجراً لهم."},{"id":"557","jozz":"5","page":"88","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"13","aya_no":"64","aya_text":"وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذۡنِ ٱللَّهِۚ وَلَوۡ أَنَّهُمۡ إِذ ظَّلَمُوٓاْ أَنفُسَهُمۡ جَآءُوكَ فَٱسۡتَغۡفَرُواْ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُواْ ٱللَّهَ تَوَّابٗا رَّحِيمٗا","aya_text_emlaey":"وما أرسلنا من رسول إلا ليطاع بإذن الله ولو أنهم إذ ظلموا أنفسهم جاءوك فاستغفروا الله واستغفر لهم الرسول لوجدوا الله توابا رحيما","aya_tafseer":"[64] وما بعَثْنا مِن رسول مِن رسلنا، إلا ليستجاب له، بأمر الله تعالى وقضائه. ولو أن هؤلاء الذين ظلموا أنفسهم باقتراف السيئات، جاؤوك -أيها الرسول- في حياتك تائبين سائلين الله أن يغفر لهم ذنوبهم، واستغفرت لهم، لوجدوا الله توَّاباً رحيماً."},{"id":"558","jozz":"5","page":"88","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"15","aya_no":"65","aya_text":"فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُمَّ لَا يَجِدُواْ فِيٓ أَنفُسِهِمۡ حَرَجٗا مِّمَّا قَضَيۡتَ وَيُسَلِّمُواْ تَسۡلِيمٗا","aya_text_emlaey":"فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجا مما قضيت ويسلموا تسليما","aya_tafseer":"[65] أقسم الله تعالى بنفسه الكريمة أن هؤلاء لا يؤمنون حقيقة حتى يجعلوك حكماً فيما وقع بينهم من نزاع في حياتك، ويتحاكموا إلى سنتك بعد مماتك، ثم لا يجدوا في أنفسهم ضيقاً مما انتهى إليه حكمك، وينقادوا مع ذلك انقياداً تامّاً، فالحكم بما جاء به رسول الله -صلى الله عليه وسلم- من الكتاب والسنة في كل شأن من شؤون الحياة من صميم الإيمان مع الرضا والتسليم."},{"id":"559","jozz":"5","page":"89","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"3","aya_no":"66","aya_text":"وَلَوۡ أَنَّا كَتَبۡنَا عَلَيۡهِمۡ أَنِ ٱقۡتُلُوٓاْ أَنفُسَكُمۡ أَوِ ٱخۡرُجُواْ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٞ مِّنۡهُمۡۖ وَلَوۡ أَنَّهُمۡ فَعَلُواْ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيۡرٗا لَّهُمۡ وَأَشَدَّ تَثۡبِيتٗا","aya_text_emlaey":"ولو أنا كتبنا عليهم أن اقتلوا أنفسكم أو اخرجوا من دياركم ما فعلوه إلا قليل منهم ولو أنهم فعلوا ما يوعظون به لكان خيرا لهم وأشد تثبيتا","aya_tafseer":"[66] ولو أوجبنا على هؤلاء المنافقين المتحاكمين إلى الطاغوت أن يقتل بعضهم بعضاً، أو أن يخرجوا من ديارهم، ما استجاب لذلك إلا عدد قليل منهم، ولو أنهم استجابوا لما يُنصحون به لكان ذلك نافعاً لهم، وأقوى لإيمانهم،"},{"id":"560","jozz":"5","page":"89","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"4","aya_no":"67","aya_text":"وَإِذٗا لَّأٓتَيۡنَٰهُم مِّن لَّدُنَّآ أَجۡرًا عَظِيمٗا","aya_text_emlaey":"وإذا لآتيناهم من لدنا أجرا عظيما","aya_tafseer":"[67] ولأعطيناهم مِن عندنا ثواباً عظيماً في الدنيا والآخرة."},{"id":"561","jozz":"5","page":"89","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"4","aya_no":"68","aya_text":"وَلَهَدَيۡنَٰهُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا","aya_text_emlaey":"ولهديناهم صراطا مستقيما","aya_tafseer":"[68] ولأرشدناهم ووفقناهم إلى طريق الله القويم"},{"id":"562","jozz":"5","page":"89","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"5","line_end":"7","aya_no":"69","aya_text":"وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّٰلِحِينَۚ وَحَسُنَ أُوْلَٰٓئِكَ رَفِيقٗا","aya_text_emlaey":"ومن يطع الله والرسول فأولئك مع الذين أنعم الله عليهم من النبيين والصديقين والشهداء والصالحين وحسن أولئك رفيقا","aya_tafseer":"[69] ومن يستجب لأوامر الله تعالى وهدي رسوله محمد -صلى الله عليه وسلم- فأولئك الذين عَظُم شأنهم وقدرهم، فكانوا في صحبة مَن أنعم الله تعالى عليهم بالجنة، من الأنبياء والصديقين الذين كمُل تصديقهم بما جاءت به الرسل، اعتقاداً وقولاً وعملاً، والشهداء في سبيل الله وصالح المؤمنين، وحَسُنَ هؤلاء رفقاء في الجنة."},{"id":"563","jozz":"5","page":"89","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"8","aya_no":"70","aya_text":"ذَٰلِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ عَلِيمٗا","aya_text_emlaey":"ذلك الفضل من الله وكفى بالله عليما","aya_tafseer":"[70] ذلك العطاء الجزيل من الله وحده. وكفى بالله عليماً يعلم أحوال عباده، ومَن يَستحقُّ منهم الثواب الجزيل بما قام به من الأعمال الصالحة."},{"id":"564","jozz":"5","page":"89","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"9","aya_no":"71","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ خُذُواْ حِذۡرَكُمۡ فَٱنفِرُواْ ثُبَاتٍ أَوِ ٱنفِرُواْ جَمِيعٗا","aya_text_emlaey":"ياأيها الذين آمنوا خذوا حذركم فانفروا ثبات أو انفروا جميعا","aya_tafseer":"[71] يا أيها الذين آمنوا خذوا حذركم بالاستعداد لعدوكم، فاخرجوا لملاقاته جماعة بعد جماعة أو مجتمعين."},{"id":"565","jozz":"5","page":"89","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"11","aya_no":"72","aya_text":"وَإِنَّ مِنكُمۡ لَمَن لَّيُبَطِّئَنَّ فَإِنۡ أَصَٰبَتۡكُم مُّصِيبَةٞ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَيَّ إِذۡ لَمۡ أَكُن مَّعَهُمۡ شَهِيدٗا","aya_text_emlaey":"وإن منكم لمن ليبطئن فإن أصابتكم مصيبة قال قد أنعم الله علي إذ لم أكن معهم شهيدا","aya_tafseer":"[72] وإنَّ منكم لنفراً يتأخر عن الخروج لملاقاة الأعداء متثاقلاً، ويثبط غيره عن عَمْد وإصرار، فإن قُدِّر عليكم وأُصِبتم بقتل وهزيمة، قال مستبشراً: قد حفظني الله، حين لم أكن حاضراً مع أولئك الذين وقع لهم ما أكرهه لنفسي، وسرَّه تخلفه عنكم."},{"id":"566","jozz":"5","page":"89","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"11","line_end":"13","aya_no":"73","aya_text":"وَلَئِنۡ أَصَٰبَكُمۡ فَضۡلٞ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةٞ يَٰلَيۡتَنِي كُنتُ مَعَهُمۡ فَأَفُوزَ فَوۡزًا عَظِيمٗا","aya_text_emlaey":"ولئن أصابكم فضل من الله ليقولن كأن لم تكن بينكم وبينه مودة ياليتني كنت معهم فأفوز فوزا عظيما","aya_tafseer":"[73] ولئن نالكم فضل من الله وغنيمة، ليقولنَّ -حاسداً متحسراً، كأن لم تكن بينكم وبينه مودة في الظاهر-: يا ليتني كنت معهم فأظفر بما ظَفِروا به من النجاة والنصرة والغنيمة."},{"id":"567","jozz":"5","page":"89","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"15","aya_no":"74","aya_text":"۞ فَلۡيُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشۡرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۚ وَمَن يُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ فَيُقۡتَلۡ أَوۡ يَغۡلِبۡ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا","aya_text_emlaey":"فليقاتل في سبيل الله الذين يشرون الحياة الدنيا بالآخرة ومن يقاتل في سبيل الله فيقتل أو يغلب فسوف نؤتيه أجرا عظيما","aya_tafseer":"[74] فليجاهد في سبيل نصرة دين الله، وإعلاء كلمته، الذين يبيعون الحياة الدنيا بالدار الآخرة وثوابها. ومن يجاهد في سبيل الله مخلصاً، فيُقْتَلْ أو يَغْلِبْ، فسوف نؤتيه أجراً عظيماً."},{"id":"568","jozz":"5","page":"90","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"3","aya_no":"75","aya_text":"وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخۡرِجۡنَا مِنۡ هَٰذِهِ ٱلۡقَرۡيَةِ ٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا","aya_text_emlaey":"وما لكم لا تقاتلون في سبيل الله والمستضعفين من الرجال والنساء والولدان الذين يقولون ربنا أخرجنا من هذه القرية الظالم أهلها واجعل لنا من لدنك وليا واجعل لنا من لدنك نصيرا","aya_tafseer":"[75] وما الذي يمنعكم -أيها المؤمنون- عن الجهاد في سبيل نصرة دين الله، ونصرة عباده المستضعفين من الرجال والنساء والصغار الذين اعتُدِي عليهم، ولا حيلة لهم ولا وسيلة لديهم إلا الاستغاثة بربهم، يدعونه قائلين: ربنا أخرجنا من هذه القرية -يعني «مكة»- التي ظَلَم أهلها أنفسهم بالكفر والمؤمنين بالأذى، واجعل لنا من عندك وليّاً يتولى أمورنا، ونصيراً ينصرنا على الظالمين؟"},{"id":"569","jozz":"5","page":"90","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"6","aya_no":"76","aya_text":"ٱلَّذِينَ ءَامَنُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ وَٱلَّذِينَ كَفَرُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱلطَّٰغُوتِ فَقَٰتِلُوٓاْ أَوۡلِيَآءَ ٱلشَّيۡطَٰنِۖ إِنَّ كَيۡدَ ٱلشَّيۡطَٰنِ كَانَ ضَعِيفًا","aya_text_emlaey":"الذين آمنوا يقاتلون في سبيل الله والذين كفروا يقاتلون في سبيل الطاغوت فقاتلوا أولياء الشيطان إن كيد الشيطان كان ضعيفا","aya_tafseer":"[76] الذين صَدَقوا في إيمانهم اعتقاداً وعملاً يجاهدون في سبيل نصرة الحق وأهله، والذين كفروا يقاتلون في سبيل البغي والفساد في الأرض، فقاتلوا أيها المؤمنون أهل الكفر والشرك الذين يتولَّون الشيطان، ويطيعون أمره، إن تدبير الشيطان لأوليائه كان ضعيفاً."},{"id":"570","jozz":"5","page":"90","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"10","aya_no":"77","aya_text":"أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقٞ مِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةٗۚ وَقَالُواْ رَبَّنَا لِمَ كَتَبۡتَ عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖۗ قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ وَٱلۡأٓخِرَةُ خَيۡرٞ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلًا","aya_text_emlaey":"ألم تر إلى الذين قيل لهم كفوا أيديكم وأقيموا الصلاة وآتوا الزكاة فلما كتب عليهم القتال إذا فريق منهم يخشون الناس كخشية الله أو أشد خشية وقالوا ربنا لم كتبت علينا القتال لولا أخرتنا إلى أجل قريب قل متاع الدنيا قليل والآخرة خير لمن اتقى ولا تظلمون فتيلا","aya_tafseer":"[77] ألم تعلم -أيها الرسول- أمر أولئك الذين قيل لهم قبل الإذن بالجهاد: امنعوا أيديكم عن قتال أعدائكم من المشركين، وعليكم أداء ما فرضه الله عليكم من الصلاة والزكاة، فلما فرض عليهم القتال إذا جماعة منهم قد تغيَّر حالهم، فأصبحوا يخافون الناس ويرهبونهم، كخوفهم من الله أو أشد، ويعلنون عما اعتراهم من شدة الخوف، فيقولون: ربنا لِمَ أَوْجَبْتَ علينا القتال؟ هلَّا أمهلتنا إلى وقت قريب، رغبة منهم في متاع الحياة الدنيا، قل لهم -أيها الرسول-: متاع الدنيا قليل، والآخرة وما فيها أعظم وأبقى لمن اتقى، فعمل بما أُمر به، واجتنب ما نُهي عنه. ولا يظلم ربك أحداً شيئاً، ولو كان مقدار الخيط الذي يكون في شق نَواة التمرة."},{"id":"571","jozz":"5","page":"90","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"14","aya_no":"78","aya_text":"أَيۡنَمَا تَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِي بُرُوجٖ مُّشَيَّدَةٖۗ وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا","aya_text_emlaey":"أينما تكونوا يدرككم الموت ولو كنتم في بروج مشيدة وإن تصبهم حسنة يقولوا هذه من عند الله وإن تصبهم سيئة يقولوا هذه من عندك قل كل من عند الله فمال هؤلاء القوم لا يكادون يفقهون حديثا","aya_tafseer":"[78] أينما تكونوا يلحقكم الموت في أي مكان كنتم فيه عند حلول آجالكم، ولو كنتم في حصون منيعة بعيدة عن ساحة المعارك والقتال. وإن يحصل لهم ما يسرُّهم من متاع هذه الحياة، ينسبوا حصوله إلى الله تعالى، وإن يَقَع عليهم ما يكرهونه ينسبوه إلى الرسول محمد -صلى الله عليه وسلم- جهالة وتشاؤماً، وما علموا أن ذلك كله من عند الله وحده، بقضائه وقدره، فما بالهم لا يقاربون فَهْمَ أيِّ حديث تحدثهم به؟"},{"id":"572","jozz":"5","page":"90","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"14","line_end":"15","aya_no":"79","aya_text":"مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولٗاۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا","aya_text_emlaey":"ما أصابك من حسنة فمن الله وما أصابك من سيئة فمن نفسك وأرسلناك للناس رسولا وكفى بالله شهيدا","aya_tafseer":"[79] ما أصابك -أيها الإنسان- مِن خير ونعمة فهو من الله تعالى وحده، فضلاً وإحساناً، وما أصابك من جهد وشدة فبسبب عملك السيِّئ، وما اقترفته يداك من الخطايا والسيئات. وبعثناك -أيها الرسول- لعموم الناس رسولاً تبلغهم رسالة ربك، وكفى بالله شهيداً على صدق رسالتك."},{"id":"573","jozz":"5","page":"91","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"2","aya_no":"80","aya_text":"مَّن يُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗا","aya_text_emlaey":"من يطع الرسول فقد أطاع الله ومن تولى فما أرسلناك عليهم حفيظا","aya_tafseer":"[80] من يستجب للرسول -صلى الله عليه وسلم-، ويعمل بهديه، فقد استجاب لله تعالى وامتثل أمره، ومن أعرض عن طاعة الله ورسوله فما بعثناك -أيها الرسول- على هؤلاء المعرضين رقيباً تحفظ أعمالهم وتحاسبهم عليها، فحسابهم علينا."},{"id":"574","jozz":"5","page":"91","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"2","line_end":"4","aya_no":"81","aya_text":"وَيَقُولُونَ طَاعَةٞ فَإِذَا بَرَزُواْ مِنۡ عِندِكَ بَيَّتَ طَآئِفَةٞ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ وَٱللَّهُ يَكۡتُبُ مَا يُبَيِّتُونَۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا","aya_text_emlaey":"ويقولون طاعة فإذا برزوا من عندك بيت طائفة منهم غير الذي تقول والله يكتب ما يبيتون فأعرض عنهم وتوكل على الله وكفى بالله وكيلا","aya_tafseer":"[81] ويُظْهر هؤلاء المعرضون -وهم في مجلس رسول الله صلى الله عليه وسلم- طاعتهم للرسول وما جاء به، فإذا ابتعدوا عنه وانصرفوا عن مجلسه، دبَّر جماعة منهم ليلاً غير ما أعلنوه من الطاعة، وما علموا أن الله يحصي عليهم ما يدبِّرون، وسيجازيهم عليه أتم الجزاء، فتولَّ عنهم -أيها الرسول- ولا تبال بهم، فإنهم لن يضروك، وتوكل على الله، وحسبك به وليّاً وناصراً."},{"id":"575","jozz":"5","page":"91","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"5","line_end":"6","aya_no":"82","aya_text":"أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا","aya_text_emlaey":"أفلا يتدبرون القرآن ولو كان من عند غير الله لوجدوا فيه اختلافا كثيرا","aya_tafseer":"[82] أفلا ينظر هؤلاء في القرآن، وما جاء به من الحق، نظر تأمل وتدبر، حيث جاء على نسق محكم يقطع بأنه من عند الله وحده؟ ولو كان مِن عند غيره لوجدوا فيه اختلافاً كثيراً."},{"id":"576","jozz":"5","page":"91","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"9","aya_no":"83","aya_text":"وَإِذَا جَآءَهُمۡ أَمۡرٞ مِّنَ ٱلۡأَمۡنِ أَوِ ٱلۡخَوۡفِ أَذَاعُواْ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّيۡطَٰنَ إِلَّا قَلِيلٗا","aya_text_emlaey":"وإذا جاءهم أمر من الأمن أو الخوف أذاعوا به ولو ردوه إلى الرسول وإلى أولي الأمر منهم لعلمه الذين يستنبطونه منهم ولولا فضل الله عليكم ورحمته لاتبعتم الشيطان إلا قليلا","aya_tafseer":"[83] وإذا جاء هؤلاء الذين لم يستقر الإيمان في قلوبهم أمْرٌ يجب كتمانه، متعلقاً بالأمن الذي يعود خيره على الإسلام والمسلمين، أو بالخوف الذي يلقي في قلوبهم عدم الاطمئنان، أفشَوْه وأذاعوا به في الناس، ولو ردَّ هؤلاء ما جاءهم إلى رسول الله -صلى الله عليه وسلم- وإلى أهل العلم والفقه لَعَلِمَ حقيقة معناه أهل الاستنباط منهم. ولولا أنْ تفضَّلَ الله عليكم ورحمكم لاتبعتم الشيطان ووساوسه إلا قليلاً منكم."},{"id":"577","jozz":"5","page":"91","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"12","aya_no":"84","aya_text":"فَقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ وَحَرِّضِ ٱلۡمُؤۡمِنِينَۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأۡسَ ٱلَّذِينَ كَفَرُواْۚ وَٱللَّهُ أَشَدُّ بَأۡسٗا وَأَشَدُّ تَنكِيلٗا","aya_text_emlaey":"فقاتل في سبيل الله لا تكلف إلا نفسك وحرض المؤمنين عسى الله أن يكف بأس الذين كفروا والله أشد بأسا وأشد تنكيلا","aya_tafseer":"[84] فجاهد -أيها النبي- في سبيل الله وإعلاء كلمته، لا تُلْزَم فِعْلَ غيرك ولا تؤاخذ به، وحُضَّ المؤمنين على القتال والجهاد، ورغِّبهم فيه، لعل الله يمنع بك وبهم بأس الكافرين وشدتهم. والله تعالى أشد قوة وأعظم عقوبة للكافرين."},{"id":"578","jozz":"5","page":"91","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"14","aya_no":"85","aya_text":"مَّن يَشۡفَعۡ شَفَٰعَةً حَسَنَةٗ يَكُن لَّهُۥ نَصِيبٞ مِّنۡهَاۖ وَمَن يَشۡفَعۡ شَفَٰعَةٗ سَيِّئَةٗ يَكُن لَّهُۥ كِفۡلٞ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقِيتٗا","aya_text_emlaey":"من يشفع شفاعة حسنة يكن له نصيب منها ومن يشفع شفاعة سيئة يكن له كفل منها وكان الله على كل شيء مقيتا","aya_tafseer":"[85] من يَسْعَ لحصول غيره على الخير يكن له بشفاعته نصيب من الثواب، ومن يَسْعَ لإيصال الشر إلى غيره يكن له نصيب من الوزر والإثم. وكان الله على كل شيء شاهداً وحفيظاً."},{"id":"579","jozz":"5","page":"91","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"14","line_end":"15","aya_no":"86","aya_text":"وَإِذَا حُيِّيتُم بِتَحِيَّةٖ فَحَيُّواْ بِأَحۡسَنَ مِنۡهَآ أَوۡ رُدُّوهَآۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٍ حَسِيبًا","aya_text_emlaey":"وإذا حييتم بتحية فحيوا بأحسن منها أو ردوها إن الله كان على كل شيء حسيبا","aya_tafseer":"[86] وإذا سلَّم عليكم المسلم فردُّوا عليه بأفضل مما سلَّم لفظاً وبشاشة، أو ردُّوا عليه بمثل ما سلَّم ، ولكلٍّ ثوابه وجزاؤه. إن الله تعالى كان على كل شيء مجازياً."},{"id":"580","jozz":"5","page":"92","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"2","aya_no":"87","aya_text":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۗ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِيثٗا","aya_text_emlaey":"الله لا إله إلا هو ليجمعنكم إلى يوم القيامة لا ريب فيه ومن أصدق من الله حديثا","aya_tafseer":"[87] الله وحده المتفرد بالألوهية لجميع الخلق، ليجمعنكم يوم القيامة، الذي لا شك فيه؛ للحساب والجزاء. ولا أحد أصدق من الله حديثاً فيما أخبر به."},{"id":"581","jozz":"5","page":"92","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"2","line_end":"4","aya_no":"88","aya_text":"۞ فَمَا لَكُمۡ فِي ٱلۡمُنَٰفِقِينَ فِئَتَيۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوٓاْۚ أَتُرِيدُونَ أَن تَهۡدُواْ مَنۡ أَضَلَّ ٱللَّهُۖ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا","aya_text_emlaey":"فما لكم في المنافقين فئتين والله أركسهم بما كسبوا أتريدون أن تهدوا من أضل الله ومن يضلل الله فلن تجد له سبيلا","aya_tafseer":"[88] فما لكم -أيها المؤمنون- في شأن المنافقين إذ اختلفتم فرقتين: فرقة تقول بقتالهم وأخرى لا تقول بذلك؟ والله تعالى قد أوقعهم في الكفر والضلال بسبب سوء أعمالهم. أتودون هداية مَن صرف الله تعالى قلبه عن دينه؟ ومن خذله الله عن دينه، واتباعِ ما أمره به، فلا طريق له إلى الهدى."},{"id":"582","jozz":"5","page":"92","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"7","aya_no":"89","aya_text":"وَدُّواْ لَوۡ تَكۡفُرُونَ كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءٗۖ فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ حَتَّىٰ يُهَاجِرُواْ فِي سَبِيلِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُواْ مِنۡهُمۡ وَلِيّٗا وَلَا نَصِيرًا","aya_text_emlaey":"ودوا لو تكفرون كما كفروا فتكونون سواء فلا تتخذوا منهم أولياء حتى يهاجروا في سبيل الله فإن تولوا فخذوهم واقتلوهم حيث وجدتموهم ولا تتخذوا منهم وليا ولا نصيرا","aya_tafseer":"[89] تمنَّى المنافقون لكم -أيها المؤمنون- لو تنكرون حقيقة ما آمنت به قلوبكم، مثلما أنكروه بقلوبهم، فتكونون معهم في الإنكار سواء، فلا تتخذوا منهم أصفياء لكم، حتى يهاجروا في سبيل الله، برهاناً على صدق إيمانهم، فإن أعرضوا عما دُعُوا إليه، فخذوهم أينما كانوا واقتلوهم، ولا تتخذوا منهم وليّاً من دون الله ولا نصيراً تستنصرون به."},{"id":"583","jozz":"5","page":"92","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"11","aya_no":"90","aya_text":"إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٌ أَوۡ جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ أَن يُقَٰتِلُوكُمۡ أَوۡ يُقَٰتِلُواْ قَوۡمَهُمۡۚ وَلَوۡ شَآءَ ٱللَّهُ لَسَلَّطَهُمۡ عَلَيۡكُمۡ فَلَقَٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ يُقَٰتِلُوكُمۡ وَأَلۡقَوۡاْ إِلَيۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَيۡهِمۡ سَبِيلٗا","aya_text_emlaey":"إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق أو جاءوكم حصرت صدورهم أن يقاتلوكم أو يقاتلوا قومهم ولو شاء الله لسلطهم عليكم فلقاتلوكم فإن اعتزلوكم فلم يقاتلوكم وألقوا إليكم السلم فما جعل الله لكم عليهم سبيلا","aya_tafseer":"[90] لكن الذين يتصلون بقوم بينكم وبينهم عهد وميثاق فلا تقاتلوهم، وكذلك الذين أتَوا إليكم وقد ضاقت صدورهم وكرهوا أن يقاتلوكم، كما كرهوا أن يقاتلوا قومهم، فلم يكونوا معكم ولا مع قومهم، فلا تقاتلوهم، ولو شاء الله تعالى لسلَّطهم عليكم، فلقاتلوكم مع أعدائكم من المشركين، ولكن الله تعالى صرفهم عنكم بفضله وقدرته، فإن تركوكم فلم يقاتلوكم، وانقادوا إليكم مستسلمين، فليس لكم عليهم من طريق لقتالهم."},{"id":"584","jozz":"5","page":"92","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"15","aya_no":"91","aya_text":"سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأۡمَنُوكُمۡ وَيَأۡمَنُواْ قَوۡمَهُمۡ كُلَّ مَا رُدُّوٓاْ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُواْ فِيهَاۚ فَإِن لَّمۡ يَعۡتَزِلُوكُمۡ وَيُلۡقُوٓاْ إِلَيۡكُمُ ٱلسَّلَمَ وَيَكُفُّوٓاْ أَيۡدِيَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡۚ وَأُوْلَٰٓئِكُمۡ جَعَلۡنَا لَكُمۡ عَلَيۡهِمۡ سُلۡطَٰنٗا مُّبِينٗا","aya_text_emlaey":"ستجدون آخرين يريدون أن يأمنوكم ويأمنوا قومهم كل ما ردوا إلى الفتنة أركسوا فيها فإن لم يعتزلوكم ويلقوا إليكم السلم ويكفوا أيديهم فخذوهم واقتلوهم حيث ثقفتموهم وأولئكم جعلنا لكم عليهم سلطانا مبينا","aya_tafseer":"[91] ستجدون قوماً آخرين من المنافقين يودون الاطمئنان على أنفسهم من جانبكم، فيظهرون لكم الإيمان، ويودون الاطمئنان على أنفسهم من جانب قومهم الكافرين، فيظهرون لهم الكفر، كلما أعيدوا إلى موطن الكفر والكافرين، وقعوا في أسوأ حال. فهؤلاء إن لم ينصرفوا عنكم، ويقدموا إليكم الاستسلام التام، ويمنعوا أنفسهم عن قتالكم فخذوهم بقوة واقتلوهم أينما كانوا، وأولئك الذين بلغوا في هذا المسلك السيِّئ حدّاً يميزهم عمَّن عداهم، فهم الذين جعلنا لكم الحجة البينة على قتلهم وأَسْرهم."},{"id":"585","jozz":"5","page":"93","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"8","aya_no":"92","aya_text":"وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـٔٗا فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ وَهُوَ مُؤۡمِنٞ فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ فَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","aya_text_emlaey":"وما كان لمؤمن أن يقتل مؤمنا إلا خطأ ومن قتل مؤمنا خطأ فتحرير رقبة مؤمنة ودية مسلمة إلى أهله إلا أن يصدقوا فإن كان من قوم عدو لكم وهو مؤمن فتحرير رقبة مؤمنة وإن كان من قوم بينكم وبينهم ميثاق فدية مسلمة إلى أهله وتحرير رقبة مؤمنة فمن لم يجد فصيام شهرين متتابعين توبة من الله وكان الله عليما حكيما","aya_tafseer":"[92] ولا يحق لمؤمن الاعتداء على أخيه المؤمن وقتله بغير حق، إلا أن يقع منه ذلك على وجه الخطأ الذي لا عمد فيه، ومن وقع منه ذلك الخطأ فعليه عتق رقبة مؤمنة، وتسليم دية مقدرة إلى أوليائه، إلا أن يتصدقوا بها عليه ويعفوا عنه. فإن كان المقتول من قوم كفار أعداء للمؤمنين، وهو مؤمن بالله تعالى، وبما أنزل من الحق على رسوله محمد -صلى الله عليه وسلم-، فعلى قاتله عتق رقبة مؤمنة، وإن كان من قوم بينكم وبينهم عهد وميثاق، فعلى قاتله دية تسلم إلى أوليائه وعتق رقبة مؤمنة، فمن لم يجد القدرة على عتق رقبة مؤمنة، فعليه صيام شهرين متتابعين؛ ليتوب الله تعالى عليه. وكان الله تعالى عليماً بحقيقة شأن عباده، حكيماً فيما شرعه لهم."},{"id":"586","jozz":"5","page":"93","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"10","aya_no":"93","aya_text":"وَمَن يَقۡتُلۡ مُؤۡمِنٗا مُّتَعَمِّدٗا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدٗا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمٗا","aya_text_emlaey":"ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما","aya_tafseer":"[93] ومن يَعْتَدِ على مؤمن فيقتله عن عمدٍ بغير حق فعاقبته جهنم خالداً فيها، مع سخط الله تعالى عليه وطَرْدِه من رحمته إن جازاه على ذنبه، وأعدَّ الله له أشد العذاب؛ بسبب ما ارتكبه من هذه الجناية العظيمة، ولكن الله سبحانه يعفو ويتفضَّل على أهل الإيمان، فلا يجازيهم بالخلود في جهنم."},{"id":"587","jozz":"5","page":"93","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"15","aya_no":"94","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا ضَرَبۡتُمۡ فِي سَبِيلِ ٱللَّهِ فَتَبَيَّنُواْ وَلَا تَقُولُواْ لِمَنۡ أَلۡقَىٰٓ إِلَيۡكُمُ ٱلسَّلَٰمَ لَسۡتَ مُؤۡمِنٗا تَبۡتَغُونَ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٞۚ كَذَٰلِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَيۡكُمۡ فَتَبَيَّنُوٓاْۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا","aya_text_emlaey":"ياأيها الذين آمنوا إذا ضربتم في سبيل الله فتبينوا ولا تقولوا لمن ألقى إليكم السلام لست مؤمنا تبتغون عرض الحياة الدنيا فعند الله مغانم كثيرة كذلك كنتم من قبل فمن الله عليكم فتبينوا إن الله كان بما تعملون خبيرا","aya_tafseer":"[94] يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه إذا خرجتم في الأرض مجاهدين في سبيل الله فكونوا على بينة مما تأتون وتتركون، ولا تنفوا الإيمان عمن بدا منه شيء من علامات الإسلام ولم يقاتلكم؛ لاحتمال أن يكون مؤمناً يخفي إيمانه، طالبين بذلك متاع الحياة الدنيا، والله تعالى عنده من الفضل والعطاء ما يغنيكم به، كذلك كنتم في بدء الإسلام تخفون إيمانكم عن قومكم من المشركين فمَنَّ الله عليكم، وأعزَّكم بالإيمان والقوة، فكونوا على بيِّنة ومعرفة في أموركم. إن الله تعالى عليم بكل أعمالكم، مُطَّلع على دقائق أموركم، وسيجازيكم عليها."},{"id":"588","jozz":"5","page":"94","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"4","aya_no":"95","aya_text":"لَّا يَسۡتَوِي ٱلۡقَٰعِدُونَ مِنَ ٱلۡمُؤۡمِنِينَ غَيۡرُ أُوْلِي ٱلضَّرَرِ وَٱلۡمُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ فَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ عَلَى ٱلۡقَٰعِدِينَ دَرَجَةٗۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَفَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ عَلَى ٱلۡقَٰعِدِينَ أَجۡرًا عَظِيمٗا","aya_text_emlaey":"لا يستوي القاعدون من المؤمنين غير أولي الضرر والمجاهدون في سبيل الله بأموالهم وأنفسهم فضل الله المجاهدين بأموالهم وأنفسهم على القاعدين درجة وكلا وعد الله الحسنى وفضل الله المجاهدين على القاعدين أجرا عظيما","aya_tafseer":"[95] لا يتساوى المتخلفون عن الجهاد في سبيل الله -غير أصحاب الأعذار منهم- والمجاهدون في سبيل الله بأموالهم وأنفسهم، فضَّل الله تعالى المجاهدين على القاعدين، ورفع منزلتهم درجة عالية في الجنة، وقد وعد الله كُلّاً من المجاهدين بأموالهم وأنفسهم والقاعدين من أهل الأعذار الجنةَ، لِما بذلوا وضحَّوا في سبيل الحق، وفضَّل الله تعالى المجاهدين على القاعدين ثواباً جزيلاً."},{"id":"589","jozz":"5","page":"94","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"5","aya_no":"96","aya_text":"دَرَجَٰتٖ مِّنۡهُ وَمَغۡفِرَةٗ وَرَحۡمَةٗۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا","aya_text_emlaey":"درجات منه ومغفرة ورحمة وكان الله غفورا رحيما","aya_tafseer":"[96] هذا الثواب الجزيل منازل عالية في الجنات من الله تعالى لخاصة عباده المجاهدين في سبيله، ومغفرة لذنوبهم ورحمة واسعة ينعمون فيها. وكان الله غفوراً لمن تاب إليه وأناب، رحيماً بأهل طاعته، المجاهدين في سبيله."},{"id":"590","jozz":"5","page":"94","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"5","line_end":"8","aya_no":"97","aya_text":"إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡ قَالُواْ فِيمَ كُنتُمۡۖ قَالُواْ كُنَّا مُسۡتَضۡعَفِينَ فِي ٱلۡأَرۡضِۚ قَالُوٓاْ أَلَمۡ تَكُنۡ أَرۡضُ ٱللَّهِ وَٰسِعَةٗ فَتُهَاجِرُواْ فِيهَاۚ فَأُوْلَٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَسَآءَتۡ مَصِيرًا","aya_text_emlaey":"إن الذين توفاهم الملائكة ظالمي أنفسهم قالوا فيم كنتم قالوا كنا مستضعفين في الأرض قالوا ألم تكن أرض الله واسعة فتهاجروا فيها فأولئك مأواهم جهنم وساءت مصيرا","aya_tafseer":"[97] إن الذين توفَّاهم الملائكة وقد ظلموا أنفسهم بقعودهم في دار الكفر وترك الهجرة، تقول لهم الملائكة توبيخاً لهم: في أي شيء كنتم من أمر دينكم؟ فيقولون: كنا ضعفاء في أرضنا، عاجزين عن دفع الظلم والقهر عنا، فيقولون لهم توبيخاً: ألم تكن أرض الله واسعة فتخرجوا من أرضكم إلى أرض أخرى بحيث تأمنون على دينكم؟ فأولئك مثواهم النار، وَقَبُحَ هذا المرجع والمآب."},{"id":"591","jozz":"5","page":"94","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"9","aya_no":"98","aya_text":"إِلَّا ٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ لَا يَسۡتَطِيعُونَ حِيلَةٗ وَلَا يَهۡتَدُونَ سَبِيلٗا","aya_text_emlaey":"إلا المستضعفين من الرجال والنساء والولدان لا يستطيعون حيلة ولا يهتدون سبيلا","aya_tafseer":"[98] ويعذر من ذاك المصير العجزة من الرجال والنساء والصغار، الذين لا يقدرون على دفع القهر والظلم عنهم، ولا يعرفون طريقاً يخلِّصهم مما هم فيه من المعاناة."},{"id":"592","jozz":"5","page":"94","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"10","aya_no":"99","aya_text":"فَأُوْلَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورٗا","aya_text_emlaey":"فأولئك عسى الله أن يعفو عنهم وكان الله عفوا غفورا","aya_tafseer":"[99] فهؤلاء الضعفاء هم الذين يُرجى لهم من الله تعالى العفو؛ لعلمه تعالى بحقيقة أمرهم. وكان الله كثيرَ العفو يتجاوز عن سيئاتهم، ويسترها عليهم."},{"id":"593","jozz":"5","page":"94","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"13","aya_no":"100","aya_text":"۞ وَمَن يُهَاجِرۡ فِي سَبِيلِ ٱللَّهِ يَجِدۡ فِي ٱلۡأَرۡضِ مُرَٰغَمٗا كَثِيرٗا وَسَعَةٗۚ وَمَن يَخۡرُجۡ مِنۢ بَيۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدۡرِكۡهُ ٱلۡمَوۡتُ فَقَدۡ وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا","aya_text_emlaey":"ومن يهاجر في سبيل الله يجد في الأرض مراغما كثيرا وسعة ومن يخرج من بيته مهاجرا إلى الله ورسوله ثم يدركه الموت فقد وقع أجره على الله وكان الله غفورا رحيما","aya_tafseer":"[100] ومَن يخرج من أرض الشرك إلى أرض الإسلام فراراً بدينه، راجياً فضل ربه، قاصداً نصرة دينه، يجد في الأرض مكاناً ومتحولاً ينعم فيه بما يكون سبباً في قوته وذلة أعدائه، مع السَّعَة في رزقه وعيشه، ومن يخرج من بيته قاصداً نصرة دين الله ورسوله -صلى الله عليه وسلم-، وإعلاء كلمة الله، ثم يدركه الموت قبل بلوغه مقصده، فقد ثبت له جزاء عمله على الله، فضلاً منه وإحساناً. وكان الله غفوراً رحيماً بعباده."},{"id":"594","jozz":"5","page":"94","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"15","aya_no":"101","aya_text":"وَإِذَا ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوّٗا مُّبِينٗا","aya_text_emlaey":"وإذا ضربتم في الأرض فليس عليكم جناح أن تقصروا من الصلاة إن خفتم أن يفتنكم الذين كفروا إن الكافرين كانوا لكم عدوا مبينا","aya_tafseer":"[101] وإذا سافرتم -أيها المؤمنون- في أرض الله، فلا حرج ولا إثم عليكم في قَصْر الصلاة إن خفتم من عدوان الكفار عليكم في حال صلاتكم، وكانت غالب أسفار المسلمين في بدء الإسلام مخوفة، والقَصْرُ رخصة في السفر حال الأمن أو الخوف. إن الكافرين مجاهرون لكم بعداوتهم، فاحذروهم."},{"id":"595","jozz":"5","page":"95","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"8","aya_no":"102","aya_text":"وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةٞ مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةٗ وَٰحِدَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ أَذٗى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا","aya_text_emlaey":"وإذا كنت فيهم فأقمت لهم الصلاة فلتقم طائفة منهم معك وليأخذوا أسلحتهم فإذا سجدوا فليكونوا من ورائكم ولتأت طائفة أخرى لم يصلوا فليصلوا معك وليأخذوا حذرهم وأسلحتهم ود الذين كفروا لو تغفلون عن أسلحتكم وأمتعتكم فيميلون عليكم ميلة واحدة ولا جناح عليكم إن كان بكم أذى من مطر أو كنتم مرضى أن تضعوا أسلحتكم وخذوا حذركم إن الله أعد للكافرين عذابا مهينا","aya_tafseer":"[102] وإذا كنت -أيها النبي- في ساحة القتال، فأردت أن تصلي بهم، فلتقم جماعة منهم معك للصلاة، وليأخذوا سلاحهم، فإذا سجد هؤلاء فلتكن الجماعة الأخرى مِن خلفكم في مواجهة عدوكم، وتُتِم الجماعة الأولى ركعتهم الثانية ويُسَلِّمون، ثم تأتي الجماعة الأخرى التي لم تبدأ الصلاة فليأتموا بك في ركعتهم الأولى، ثم يكملوا بأنفسهم ركعتهم الثانية، وليحذروا مِن عدوهم وليأخذوا أسلحتهم. وَدَّ الجاحدون لدين الله أن تغفُلوا عن سلاحكم وزادكم؛ ليحملوا عليكم حملة واحدة فيقضوا عليكم، ولا إثم عليكم حينئذ إن كان بكم أذى من مطر، أو كنتم في حال مرض أن تتركوا أسلحتكم، مع أَخْذِ الحذر. إن الله تعالى أعدَّ للجاحدين لدينه عذاباً يُهينهم، ويُخزيهم."},{"id":"596","jozz":"5","page":"95","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"11","aya_no":"103","aya_text":"فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبٗا مَّوۡقُوتٗا","aya_text_emlaey":"فإذا قضيتم الصلاة فاذكروا الله قياما وقعودا وعلى جنوبكم فإذا اطمأننتم فأقيموا الصلاة إن الصلاة كانت على المؤمنين كتابا موقوتا","aya_tafseer":"[103] فإذا أدَّيتم الصلاة، فأديموا ذكر الله في جميع أحوالكم، فإذا زال الخوف فأدُّوا الصلاة كاملة، ولا تفرِّطوا فيها فإنها واجبة في أوقات معلومة في الشرع."},{"id":"597","jozz":"5","page":"95","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"11","line_end":"14","aya_no":"104","aya_text":"وَلَا تَهِنُواْ فِي ٱبۡتِغَآءِ ٱلۡقَوۡمِۖ إِن تَكُونُواْ تَأۡلَمُونَ فَإِنَّهُمۡ يَأۡلَمُونَ كَمَا تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا يَرۡجُونَۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا","aya_text_emlaey":"ولا تهنوا في ابتغاء القوم إن تكونوا تألمون فإنهم يألمون كما تألمون وترجون من الله ما لا يرجون وكان الله عليما حكيما","aya_tafseer":"[104] ولا تضعفوا في طلب عدوكم وقتاله، إن تكونوا تتألمون من القتال وآثاره، فأعداؤكم كذلك يتألمون منه أشد الألم، ومع ذلك لا يكفون عن قتالكم، فأنتم أولى بذلك منهم؛ لما ترجونه من الثواب والنصر والتأييد، وهم لا يرجون ذلك. وكان الله عليماً بكل أحوالكم، حكيماً في أمره وتدبيره."},{"id":"598","jozz":"5","page":"95","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"14","line_end":"15","aya_no":"105","aya_text":"إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ بَيۡنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَآئِنِينَ خَصِيمٗا","aya_text_emlaey":"إنا أنـزلنا إليك الكتاب بالحق لتحكم بين الناس بما أراك الله ولا تكن للخائنين خصيما","aya_tafseer":"[105] إنا أنزلنا إليك -أيها الرسول- القرآن مشتملاً على الحق؛ لتفصل بين الناس جميعاً بما أوحى الله إليك، وبَصَّرك به، فلا تكن للذين يخونون أنفسهم -بكتمان الحق- مدافعاً عنهم؛ بما أبدوه لك من القول المخالف للحقيقة."},{"id":"599","jozz":"5","page":"96","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"1","aya_no":"106","aya_text":"وَٱسۡتَغۡفِرِ ٱللَّهَۖ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا","aya_text_emlaey":"واستغفر الله إن الله كان غفورا رحيما","aya_tafseer":"[106] واطلب من الله تعالى المغفرة في جميع أحوالك، إن الله تعالى كان غفوراً لمن يرجو فضله ونوال مغفرته، رحيماً به."},{"id":"600","jozz":"5","page":"96","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"3","aya_no":"107","aya_text":"وَلَا تُجَٰدِلۡ عَنِ ٱلَّذِينَ يَخۡتَانُونَ أَنفُسَهُمۡۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمٗا","aya_text_emlaey":"ولا تجادل عن الذين يختانون أنفسهم إن الله لا يحب من كان خوانا أثيما","aya_tafseer":"[107] ولا تدافع عن الذين يخونون أنفسهم بمعصية الله. إن الله -سبحانه- لا يحب مَن عَظُمَتْ خيانته، وكثر ذنبه."},{"id":"601","jozz":"5","page":"96","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"5","aya_no":"108","aya_text":"يَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا يَسۡتَخۡفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ وَكَانَ ٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطًا","aya_text_emlaey":"يستخفون من الناس ولا يستخفون من الله وهو معهم إذ يبيتون ما لا يرضى من القول وكان الله بما يعملون محيطا","aya_tafseer":"[108] يستترون من الناس خوفاً من اطلاعهم على أعمالهم السيئة، ولا يستترون من الله تعالى ولا يستحيون منه، وهو عزَّ شأنه معهم بعلمه، مطَّلع عليهم حين يدبِّرون -ليلاً- ما لا يرضى من القول، وكان الله -تعالى- محيطاً بجميع أقوالهم وأفعالهم، لا يخفى عليه منها شيء."},{"id":"602","jozz":"5","page":"96","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"5","line_end":"7","aya_no":"109","aya_text":"هَٰٓأَنتُمۡ هَٰٓؤُلَآءِ جَٰدَلۡتُمۡ عَنۡهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنۡهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيۡهِمۡ وَكِيلٗا","aya_text_emlaey":"ها أنتم هؤلاء جادلتم عنهم في الحياة الدنيا فمن يجادل الله عنهم يوم القيامة أم من يكون عليهم وكيلا","aya_tafseer":"[109] ها أنتم -أيها المؤمنون- قد حاججتم عن هؤلاء الخائنين لأنفسهم في هذه الحياة الدنيا، فمن يحاجج الله تعالى عنهم يوم البعث والحساب؟ ومن ذا الذي يكون على هؤلاء الخائنين وكيلاً يوم القيامة؟"},{"id":"603","jozz":"5","page":"96","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"9","aya_no":"110","aya_text":"وَمَن يَعۡمَلۡ سُوٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُۥ ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورٗا رَّحِيمٗا","aya_text_emlaey":"ومن يعمل سوءا أو يظلم نفسه ثم يستغفر الله يجد الله غفورا رحيما","aya_tafseer":"[110] ومن يُقْدِمْ على عمل سيِّئ قبيح، أو يظلم نفسه بارتكاب ما يخالف حكم الله وشرعه، ثم يرجع إلى الله نادماً على ما عمل، راجياً مغفرته وستر ذنبه، يجد الله تعالى غفوراً له، رحيماً به."},{"id":"604","jozz":"5","page":"96","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"10","aya_no":"111","aya_text":"وَمَن يَكۡسِبۡ إِثۡمٗا فَإِنَّمَا يَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","aya_text_emlaey":"ومن يكسب إثما فإنما يكسبه على نفسه وكان الله عليما حكيما","aya_tafseer":"[111] ومن يعمد إلى ارتكاب ذنب فإنما يضر بذلك نفسه وحدها، وكان الله تعالى عليماً بحقيقة أمر عباده، حكيماً فيما يقضي به بين خلقه."},{"id":"605","jozz":"5","page":"96","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"11","aya_no":"112","aya_text":"وَمَن يَكۡسِبۡ خَطِيٓـَٔةً أَوۡ إِثۡمٗا ثُمَّ يَرۡمِ بِهِۦ بَرِيٓـٔٗا فَقَدِ ٱحۡتَمَلَ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا","aya_text_emlaey":"ومن يكسب خطيئة أو إثما ثم يرم به بريئا فقد احتمل بهتانا وإثما مبينا","aya_tafseer":"[112] ومن يعمل خطيئة بغير عمد، أو يرتكب ذنباً متعمداً ثم يقذف بما ارتكبه نفساً بريئة لا جناية لها، فقد تحمَّل كذباً وذنباً بيناً."},{"id":"606","jozz":"5","page":"96","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"15","aya_no":"113","aya_text":"وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّآئِفَةٞ مِّنۡهُمۡ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡۖ وَمَا يَضُرُّونَكَ مِن شَيۡءٖۚ وَأَنزَلَ ٱللَّهُ عَلَيۡكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَيۡكَ عَظِيمٗا","aya_text_emlaey":"ولولا فضل الله عليك ورحمته لهمت طائفة منهم أن يضلوك وما يضلون إلا أنفسهم وما يضرونك من شيء وأنـزل الله عليك الكتاب والحكمة وعلمك ما لم تكن تعلم وكان فضل الله عليك عظيما","aya_tafseer":"[113] ولولا أن الله تعالى قد مَنَّ عليك -أيها الرسول- ورحمك بنعمة النبوة، فعصمك بتوفيقه بما أوحى إليك، لعزمت جماعة من الذين يخونون أنفسهم أن يُزِلُّوك عن طريق الحق، وما يُزِلُّون بذلك إلا أنفسهم، وما يقدرون على إيذائك لعصمة الله لك، وأنزل الله عليك القرآن والسنة المبينة له، وهداك إلى علم ما لم تكن تعلمه مِن قبل، وكان ما خصَّك الله به مِن فضلٍ أمراً عظيماً."},{"id":"607","jozz":"5","page":"97","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"3","aya_no":"114","aya_text":"۞ لَّا خَيۡرَ فِي كَثِيرٖ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا","aya_text_emlaey":"لا خير في كثير من نجواهم إلا من أمر بصدقة أو معروف أو إصلاح بين الناس ومن يفعل ذلك ابتغاء مرضات الله فسوف نؤتيه أجرا عظيما","aya_tafseer":"[114] لا نفع في كثير من كلام الناس سرّاً فيما بينهم، إلا إذا كان حديثاً داعياً إلى بذل المعروف من الصدقة، أو الكلمة الطيبة، أو التوفيق بين الناس، ومن يفعل تلك الأمور طلباً لرضا الله تعالى راجياً ثوابه، فسوف نؤتيه ثواباً جزيلاً واسعاً."},{"id":"608","jozz":"5","page":"97","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"6","aya_no":"115","aya_text":"وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُ ٱلۡهُدَىٰ وَيَتَّبِعۡ غَيۡرَ سَبِيلِ ٱلۡمُؤۡمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرًا","aya_text_emlaey":"ومن يشاقق الرسول من بعد ما تبين له الهدى ويتبع غير سبيل المؤمنين نوله ما تولى ونصله جهنم وساءت مصيرا","aya_tafseer":"[115] ومن يخالف الرسول -صلى الله عليه وسلم- من بعد ما ظهر له الحق، ويسلك طريقاً غير طريق المؤمنين، وما هم عليه من الحق، نتركه وما توجَّه إليه، فلا نوفقه للخير، وندخله نار جهنم يقاسي حرَّها، وبئس هذا المرجع والمآل."},{"id":"609","jozz":"5","page":"97","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"8","aya_no":"116","aya_text":"إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا","aya_text_emlaey":"إن الله لا يغفر أن يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد ضل ضلالا بعيدا","aya_tafseer":"[116] إن الله تعالى لا يغفر أن يشرك به، ويغفر ما دون الشرك من الذنوب لمن يشاء من عباده. ومن يجعل لله تعالى الواحد الأحد شريكاً من خلقه، فقد بَعُدَ عن الحق بعداً كبيراً."},{"id":"610","jozz":"5","page":"97","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"9","aya_no":"117","aya_text":"إِن يَدۡعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثٗا وَإِن يَدۡعُونَ إِلَّا شَيۡطَٰنٗا مَّرِيدٗا","aya_text_emlaey":"إن يدعون من دونه إلا إناثا وإن يدعون إلا شيطانا مريدا","aya_tafseer":"[117] ما يعبد المشركون من دون الله تعالى إلَّا أوثاناً لا تنفع ولا تضرُّ، وما يعبدون إلا شيطاناً متمرداً على الله، بلغ في الفساد والإفساد حدّاً كبيراً."},{"id":"611","jozz":"5","page":"97","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"10","aya_no":"118","aya_text":"لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ مِنۡ عِبَادِكَ نَصِيبٗا مَّفۡرُوضٗا","aya_text_emlaey":"لعنه الله وقال لأتخذن من عبادك نصيبا مفروضا","aya_tafseer":"[118] طرده الله تعالى من رحمته. وقال الشيطان: لأتخذن مِن عبادك جزءاً معلوماً في إغوائهم قولاً وعملاً."},{"id":"612","jozz":"5","page":"97","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"13","aya_no":"119","aya_text":"وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّيَنَّهُمۡ وَلَأٓمُرَنَّهُمۡ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَٰمِ وَلَأٓمُرَنَّهُمۡ فَلَيُغَيِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن يَتَّخِذِ ٱلشَّيۡطَٰنَ وَلِيّٗا مِّن دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانٗا مُّبِينٗا","aya_text_emlaey":"ولأضلنهم ولأمنينهم ولآمرنهم فليبتكن آذان الأنعام ولآمرنهم فليغيرن خلق الله ومن يتخذ الشيطان وليا من دون الله فقد خسر خسرانا مبينا","aya_tafseer":"[119] ولأصرفَنَّ مَن تبعني منهم عن الحق، ولأعِدَنَّهم بالأماني الكاذبة، ولأدعونَّهم إلى تقطيع آذان الأنعام وتشقيقها لِمَا أزيِّنه لهم من الباطل، ولأدعونَّهم إلى تغيير خلق الله في الفطرة، وهيئة ما عليه الخلق. ومن يستجب للشيطان ويتخذه ناصراً له من دون الله القوي العزيز، فقد هلك هلاكاً بيِّناً."},{"id":"613","jozz":"5","page":"97","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"14","aya_no":"120","aya_text":"يَعِدُهُمۡ وَيُمَنِّيهِمۡۖ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا","aya_text_emlaey":"يعدهم ويمنيهم وما يعدهم الشيطان إلا غرورا","aya_tafseer":"[120] يَعِدُ الشيطان أتباعه بالوعود الكاذبة، ويغريهم بالأماني الباطلة الخادعة، وما يَعِدُهم إلا خديعة لا صحة لها، ولا دليل عليها."},{"id":"614","jozz":"5","page":"97","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"14","line_end":"15","aya_no":"121","aya_text":"أُوْلَٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا يَجِدُونَ عَنۡهَا مَحِيصٗا","aya_text_emlaey":"أولئك مأواهم جهنم ولا يجدون عنها محيصا","aya_tafseer":"[121] أولئك مآلهم جهنم، ولا يجدون عنها معدلاً ولا ملجأً."},{"id":"615","jozz":"5","page":"98","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"3","aya_no":"122","aya_text":"وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ وَعۡدَ ٱللَّهِ حَقّٗاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِيلٗا","aya_text_emlaey":"والذين آمنوا وعملوا الصالحات سندخلهم جنات تجري من تحتها الأنهار خالدين فيها أبدا وعد الله حقا ومن أصدق من الله قيلا","aya_tafseer":"[122] والذين صَدَقوا في إيمانهم بالله تعالى، وأتْبَعوا الإيمان بالأعمال الصالحة سيدخلهم الله -بفضله- جنات تجري من تحت قصورها وأشجارها الأنهار ماكثين فيها أبداً، وَعْداً من الله تعالى الذي لا يخلف وعده. ولا أحد أصدق من الله تعالى في قوله ووعده."},{"id":"616","jozz":"5","page":"98","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"5","aya_no":"123","aya_text":"لَّيۡسَ بِأَمَانِيِّكُمۡ وَلَآ أَمَانِيِّ أَهۡلِ ٱلۡكِتَٰبِۗ مَن يَعۡمَلۡ سُوٓءٗا يُجۡزَ بِهِۦ وَلَا يَجِدۡ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا","aya_text_emlaey":"ليس بأمانيكم ولا أماني أهل الكتاب من يعمل سوءا يجز به ولا يجد له من دون الله وليا ولا نصيرا","aya_tafseer":"[123] لا يُنال هذا الفضل العظيم بالأماني التي تتمنونها أيها المسلمون، ولا بأماني أهل الكتاب من اليهود والنصارى، وإنما يُنال بالإيمان الصادق بالله تعالى، وإحسان العمل الذي يرضيه. ومن يعمل عملاً سيئاً يُجْزَ به، ولا يجد له سوى الله تعالى وليّاً يتولى أمره وشأنه، ولا نصيراً ينصره، ويدفع عنه سوء العذاب."},{"id":"617","jozz":"5","page":"98","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"5","line_end":"7","aya_no":"124","aya_text":"وَمَن يَعۡمَلۡ مِنَ ٱلصَّٰلِحَٰتِ مِن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ نَقِيرٗا","aya_text_emlaey":"ومن يعمل من الصالحات من ذكر أو أنثى وهو مؤمن فأولئك يدخلون الجنة ولا يظلمون نقيرا","aya_tafseer":"[124] ومن يعمل من الأعمال الصالحة من ذكر أو أنثى، وهو مؤمن بالله تعالى وبما أنزل من الحق، فأولئك يدخلهم الله الجنة دارَ النعيم المقيم، ولا يُنْقَصون مِن ثواب أعمالهم شيئاً، ولو كان مقدار النُّقرة في ظهر النَّواة."},{"id":"618","jozz":"5","page":"98","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"9","aya_no":"125","aya_text":"وَمَنۡ أَحۡسَنُ دِينٗا مِّمَّنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ وَٱتَّبَعَ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۗ وَٱتَّخَذَ ٱللَّهُ إِبۡرَٰهِيمَ خَلِيلٗا","aya_text_emlaey":"ومن أحسن دينا ممن أسلم وجهه لله وهو محسن واتبع ملة إبراهيم حنيفا واتخذ الله إبراهيم خليلا","aya_tafseer":"[125] لا أحد أحسن ديناً ممن انقاد بقلبه وسائر جوارحه لله تعالى وحده، وهو محسن في قوله وعمله مُتَّبِعٌ أمرَ ربِّه، واتبع دين إبراهيم وشرعه، مائلاً عن العقائد الفاسدة والشرائع الباطلة. وقد اصطفى الله إبراهيم -عليه الصلاة والسلام- واتخذه صفيّاً من بين سائر خلقه. وفي هذه الآية، إثبات صفة الخُلَّة لله -تعالى- وهي أعلى مقامات المحبة والاصطفاء."},{"id":"619","jozz":"5","page":"98","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"11","aya_no":"126","aya_text":"وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٖ مُّحِيطٗا","aya_text_emlaey":"ولله ما في السموات وما في الأرض وكان الله بكل شيء محيطا","aya_tafseer":"[126] ولله جميع ما في هذا الكون من المخلوقات، فهي ملك له تعالى وحده. وكان الله تعالى بكل شيء محيطاً، لا يخفى عليه شيء من أمور خلقه."},{"id":"620","jozz":"5","page":"98","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"11","line_end":"15","aya_no":"127","aya_text":"وَيَسۡتَفۡتُونَكَ فِي ٱلنِّسَآءِۖ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِيهِنَّ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ فِي يَتَٰمَى ٱلنِّسَآءِ ٱلَّٰتِي لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلۡوِلۡدَٰنِ وَأَن تَقُومُواْ لِلۡيَتَٰمَىٰ بِٱلۡقِسۡطِۚ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمٗا","aya_text_emlaey":"ويستفتونك في النساء قل الله يفتيكم فيهن وما يتلى عليكم في الكتاب في يتامى النساء اللاتي لا تؤتونهن ما كتب لهن وترغبون أن تنكحوهن والمستضعفين من الولدان وأن تقوموا لليتامى بالقسط وما تفعلوا من خير فإن الله كان به عليما","aya_tafseer":"[127] يطلب الناس منك -أيها النبي- أن تبين لهم ما أشكل عليهم فَهْمُه من قضايا النساء وأحكامهن، قل الله تعالى يبيِّن لكم أمورهن، وما يتلى عليكم في الكتاب في يتامى النساء اللاتي لا تعطونهن ما فرض الله تعالى لهن من المهر والميراث، وغير ذلك من الحقوق، وتحبون نكاحهن، أو ترغبون عن نكاحهن، ويبيِّن الله لكم أمر الضعفاء من الصغار، ووجوب القيام لليتامى -وهم الذين مات آباؤهم وهم دون سن البلوغ- بالعدل وترك الجَوْر عليهم في حقوقهم. وما تفعلوا من خير فإن الله تعالى كان به عليماً، لا يخفى عليه شيء منه ولا من غيره."},{"id":"621","jozz":"5","page":"99","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"4","aya_no":"128","aya_text":"وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضٗا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يُصۡلِحَا بَيۡنَهُمَا صُلۡحٗاۚ وَٱلصُّلۡحُ خَيۡرٞۗ وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا","aya_text_emlaey":"وإن امرأة خافت من بعلها نشوزا أو إعراضا فلا جناح عليهما أن يصلحا بينهما صلحا والصلح خير وأحضرت الأنفس الشح وإن تحسنوا وتتقوا فإن الله كان بما تعملون خبيرا","aya_tafseer":"[128] وإن علمت امرأة من زوجها ترفُّعاً عنها، وتعالياً عليها أو انصرافاً عنها فلا إثم عليهما أن يتصالحا على ما تطيب به نفوسهما من القسمة أو النفقة، والصلح أولى وأفضل. وجبلت النفوس على الحرص والبخل، فكأنَّ البخل حاضرها لا ينفكُّ عنها. وإن تحسنوا معاملة زوجاتكم وتخافوا الله فيهن، فإن الله كان بما تعملون من ذلك وغيره عالماً لا يخفى عليه شيء، وسيجازيكم على ذلك."},{"id":"622","jozz":"5","page":"99","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"7","aya_no":"129","aya_text":"وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ بَيۡنَ ٱلنِّسَآءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِيلُواْ كُلَّ ٱلۡمَيۡلِ فَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا","aya_text_emlaey":"ولن تستطيعوا أن تعدلوا بين النساء ولو حرصتم فلا تميلوا كل الميل فتذروها كالمعلقة وإن تصلحوا وتتقوا فإن الله كان غفورا رحيما","aya_tafseer":"[129] ولن تقدروا -أيها الرجال- على تحقيق العدل التام بين النساء في المحبة وميل القلب، مهما بذلتم في ذلك من الجهد، فلا تعرضوا عن المرغوب عنها كل الإعراض، فتتركوها كالمرأة التي ليست بذات زوج ولا هي مطلقة فتأثموا. وإن تصلحوا أعمالكم فتعدلوا في قَسْمكم بين زوجاتكم، وتراقبوا الله تعالى وتخشوه فيهن، فإن الله تعالى كان غفوراً لعباده، رحيماً بهم."},{"id":"623","jozz":"5","page":"99","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"8","aya_no":"130","aya_text":"وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلّٗا مِّن سَعَتِهِۦۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمٗا","aya_text_emlaey":"وإن يتفرقا يغن الله كلا من سعته وكان الله واسعا حكيما","aya_tafseer":"[130] وإن وقعت الفرقة بين الرجل وامرأته، فإن الله تعالى يغني كُلّاً منهما من فضله وسَعَته؛ فإنه سبحانه وتعالى واسع الفضل والمنة، حكيم فيما يقضي به بين عباده."},{"id":"624","jozz":"5","page":"99","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"11","aya_no":"131","aya_text":"وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا","aya_text_emlaey":"ولله ما في السموات وما في الأرض ولقد وصينا الذين أوتوا الكتاب من قبلكم وإياكم أن اتقوا الله وإن تكفروا فإن لله ما في السموات وما في الأرض وكان الله غنيا حميدا","aya_tafseer":"[131] ولله ملك ما في السموات وما في الأرض وما بينهما. ولقد عهدنا إلى الذين أُعطوا الكتاب من قبلكم من اليهود والنصارى، وعهدنا إليكم كذلك -يا أمة محمد- بتقوى الله تعالى، والقيام بأمره واجتناب نهيه، وبيَّنَّا لكم أنكم إن تجحدوا وحدانية الله تعالى وشرعه فإنه سبحانه غني عنكم؛ لأن له جميع ما في السموات وما في الأرض. وكان الله غنياً عن خلقه، حميداً في صفاته وأفعاله."},{"id":"625","jozz":"5","page":"99","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"12","aya_no":"132","aya_text":"وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا","aya_text_emlaey":"ولله ما في السموات وما في الأرض وكفى بالله وكيلا","aya_tafseer":"[132] ولله ملك ما في هذا الكون من الكائنات، وكفى به سبحانه قائماً بشؤون خلقه حافظاً لها."},{"id":"626","jozz":"5","page":"99","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"14","aya_no":"133","aya_text":"إِن يَشَأۡ يُذۡهِبۡكُمۡ أَيُّهَا ٱلنَّاسُ وَيَأۡتِ بِـَٔاخَرِينَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرٗا","aya_text_emlaey":"إن يشأ يذهبكم أيها الناس ويأت بآخرين وكان الله على ذلك قديرا","aya_tafseer":"[133] إن يشأ الله يُهلكُّم أيها الناس، ويأت بقوم آخرين غيركم. وكان الله على ذلك قديراً."},{"id":"627","jozz":"5","page":"99","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"14","line_end":"15","aya_no":"134","aya_text":"مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا","aya_text_emlaey":"من كان يريد ثواب الدنيا فعند الله ثواب الدنيا والآخرة وكان الله سميعا بصيرا","aya_tafseer":"[134] من يرغب منكم -أيها الناس- في ثواب الدنيا ويعرض عن الآخرة، فعند الله وحده ثواب الدنيا والآخرة، فليطلب من الله وحده خيري الدنيا والآخرة، فهو الذي يملكهما. وكان الله سميعاً لأقوال عباده، بصيراً بنياتهم وأعمالهم، وسيجازيهم على ذلك."},{"id":"628","jozz":"5","page":"100","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"4","aya_no":"135","aya_text":"۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا","aya_text_emlaey":"ياأيها الذين آمنوا كونوا قوامين بالقسط شهداء لله ولو على أنفسكم أو الوالدين والأقربين إن يكن غنيا أو فقيرا فالله أولى بهما فلا تتبعوا الهوى أن تعدلوا وإن تلووا أو تعرضوا فإن الله كان بما تعملون خبيرا","aya_tafseer":"[135] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، كونوا قائمين بالعدل، مؤدين للشهادة لوجه الله تعالى، ولو كانت على أنفسكم، أو على آبائكم وأمهاتكم، أو على أقاربكم، مهما كان شأن المشهود عليه غنيّاً أو فقيراً؛ فإنَّ الله تعالى أولى بهما منكم، وأعلم بما فيه صلاحهما، فلا يحملنَّكم الهوى والتعصب على ترك العدل، وإن تحرفوا الشهادة بألسنتكم فتأتوا بها على غير حقيقتها، أو تعرضوا عنها بترك أدائها أو بكتمانها، فإن الله تعالى كان عليماً بدقائق أعمالكم، وسيجازيكم بها."},{"id":"629","jozz":"5","page":"100","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"8","aya_no":"136","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِي نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِيٓ أَنزَلَ مِن قَبۡلُۚ وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا","aya_text_emlaey":"ياأيها الذين آمنوا آمنوا بالله ورسوله والكتاب الذي نـزل على رسوله والكتاب الذي أنـزل من قبل ومن يكفر بالله وملائكته وكتبه ورسله واليوم الآخر فقد ضل ضلالا بعيدا","aya_tafseer":"[136] يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه داوموا على ما أنتم عليه من التصديق الجازم بالله تعالى وبرسوله محمد -صلى الله عليه وسلم-، ومن طاعتهما، وبالقرآن الذي نزله عليه، وبجميع الكتب التي أنزلها الله على الرسل. ومن يكفر بالله تعالى، وملائكته المكرمين، وكتبه التي أنزلها لهداية خلقه، ورسله الذين اصطفاهم لتبليغ رسالته، واليوم الآخر الذي يقوم الناس فيه بعد موتهم للعرض والحساب، فقد خرج من الدين، وبَعُدَ بعداً كبيراً عن طريق الحق."},{"id":"630","jozz":"5","page":"100","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"10","aya_no":"137","aya_text":"إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ سَبِيلَۢا","aya_text_emlaey":"إن الذين آمنوا ثم كفروا ثم آمنوا ثم كفروا ثم ازدادوا كفرا لم يكن الله ليغفر لهم ولا ليهديهم سبيلا","aya_tafseer":"[137] إن الذين دخلوا في الإيمان، ثم رجعوا عنه إلى الكفر، ثم عادوا إلى الإيمان، ثم رجعوا إلى الكفر مرة أخرى، ثم أصرُّوا على كفرهم واستمروا عليه، لم يكن الله ليغفر لهم، ولا ليدلهم على طريق من طرق الهداية، التي ينجون بها من سوء العاقبة."},{"id":"631","jozz":"5","page":"100","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"10","aya_no":"138","aya_text":"بَشِّرِ ٱلۡمُنَٰفِقِينَ بِأَنَّ لَهُمۡ عَذَابًا أَلِيمًا","aya_text_emlaey":"بشر المنافقين بأن لهم عذابا أليما","aya_tafseer":"[138] بَشِّر -أيها الرسول- المنافقين -وهم الذين يظهرون الإيمان ويبطنون الكفر- بأن لهم عذاباً موجعاً."},{"id":"632","jozz":"5","page":"100","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"12","aya_no":"139","aya_text":"ٱلَّذِينَ يَتَّخِذُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَيَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعٗا","aya_text_emlaey":"الذين يتخذون الكافرين أولياء من دون المؤمنين أيبتغون عندهم العزة فإن العزة لله جميعا","aya_tafseer":"[139] الذين يوالون الكافرين، ويتخذونهم أعواناً لهم، ويتركون ولاية المؤمنين، ولا يرغبون في مودتهم. أيطلبون بذلك النصرة والمنعة عند الكافرين؟ إنهم لا يملكون ذلك، فالنصرة والعزة والقوة جميعها لله تعالى وحده."},{"id":"633","jozz":"5","page":"100","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"15","aya_no":"140","aya_text":"وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذٗا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا","aya_text_emlaey":"وقد نـزل عليكم في الكتاب أن إذا سمعتم آيات الله يكفر بها ويستهزأ بها فلا تقعدوا معهم حتى يخوضوا في حديث غيره إنكم إذا مثلهم إن الله جامع المنافقين والكافرين في جهنم جميعا","aya_tafseer":"[140] وقد نَزَّل ربُّكم عليكم -أيها المؤمنون- في كتابه أنه إذا سمعتم الكفر بآيات الله والاستهزاء بها فلا تجلسوا مع الكافرين والمستهزئين، إلا إذا أخذوا في حديث غير حديث الكفر والاستهزاء بآيات الله. إنكم إذا جالستموهم، وهم على ما هم عليه، فأنتم مثلهم؛ لأنكم رضيتم بكفرهم واستهزائهم، والراضي بالمعصية كالفاعل لها. إن الله تعالى جامع المنافقين والكافرين في نار جهنم جميعاً، يَلْقَون فيها سوء العذاب."},{"id":"634","jozz":"5","page":"101","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"5","aya_no":"141","aya_text":"ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحٞ مِّنَ ٱللَّهِ قَالُوٓاْ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبٞ قَالُوٓاْ أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ سَبِيلًا","aya_text_emlaey":"الذين يتربصون بكم فإن كان لكم فتح من الله قالوا ألم نكن معكم وإن كان للكافرين نصيب قالوا ألم نستحوذ عليكم ونمنعكم من المؤمنين فالله يحكم بينكم يوم القيامة ولن يجعل الله للكافرين على المؤمنين سبيلا","aya_tafseer":"[141] المنافقون هم الذين ينتظرون ما يحلُّ بكم -أيها المؤمنون- من الفتن والحرب، فإن منَّ الله عليكم بفضله، ونصركم على عدوكم وغنمتم، قالوا لكم: ألم نكن معكم نؤازركم؟ وإن كان للجاحدين لهذا الدين قدْرٌ من النصر والغنيمة، قالوا لهم: ألم نساعدكم بما قدَّمْناه لكم ونَحْمِكم من المؤمنين؟ فالله تعالى يقضي بينكم وبينهم يوم القيامة، ولن يجعل الله للكافرين طريقاً للغلبة على عباده الصالحين، فالعاقبة للمتقين في الدنيا والآخرة."},{"id":"635","jozz":"5","page":"101","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"5","line_end":"7","aya_no":"142","aya_text":"إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِيلٗا","aya_text_emlaey":"إن المنافقين يخادعون الله وهو خادعهم وإذا قاموا إلى الصلاة قاموا كسالى يراءون الناس ولا يذكرون الله إلا قليلا","aya_tafseer":"[142] إنَّ طريقة هؤلاء المنافقين مُخَادَعَةُ اللهِ تعالى، بما يظهرونه من الإيمان وما يبطنونه من الكفر، ظنّاً أنه يخفى على الله، والحال أن الله خادعهم ومجازيهم بمثل عملهم، وإذا قام هؤلاء المنافقون لأداء الصلاة، قاموا إليها في فتور، يقصدون بصلاتهم الرياء والسمعة، ولا يذكرون الله تعالى إلا ذكراً قليلاً."},{"id":"636","jozz":"5","page":"101","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"8","aya_no":"143","aya_text":"مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَٰٓؤُلَآءِ وَلَآ إِلَىٰ هَٰٓؤُلَآءِۚ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا","aya_text_emlaey":"مذبذبين بين ذلك لا إلى هؤلاء ولا إلى هؤلاء ومن يضلل الله فلن تجد له سبيلا","aya_tafseer":"[143] إنَّ مِن شأن هؤلاء المنافقين التردد والحَيْرة والاضطراب، لا يستقرون على حال، فلا هم مع المؤمنين ولا هم مع الكافرين. ومن يصرف الله قلبه عن الإيمان به والاستمساك بهديه، فلن تجد له طريقاً إلى الهداية واليقين."},{"id":"637","jozz":"5","page":"101","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"10","aya_no":"144","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَتُرِيدُونَ أَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنٗا مُّبِينًا","aya_text_emlaey":"ياأيها الذين آمنوا لا تتخذوا الكافرين أولياء من دون المؤمنين أتريدون أن تجعلوا لله عليكم سلطانا مبينا","aya_tafseer":"[144] يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه، لا توالوا الجاحدين لدين الله، وتتركوا موالاة المؤمنين ومودتهم. أتريدون بمودَّة أعدائكم أن تجعلوا لله تعالى عليكم حجة ظاهرة على عدم صدقكم في إيمانكم؟"},{"id":"638","jozz":"5","page":"101","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"11","aya_no":"145","aya_text":"إِنَّ ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا","aya_text_emlaey":"إن المنافقين في الدرك الأسفل من النار ولن تجد لهم نصيرا","aya_tafseer":"[145] إن المنافقين في أسفل منازل النار يوم القيامة، ولن تجد لهم -أيها الرسول- ناصراً يدفع عنهم سوء هذا المصير."},{"id":"639","jozz":"5","page":"101","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"14","aya_no":"146","aya_text":"إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَٱعۡتَصَمُواْ بِٱللَّهِ وَأَخۡلَصُواْ دِينَهُمۡ لِلَّهِ فَأُوْلَٰٓئِكَ مَعَ ٱلۡمُؤۡمِنِينَۖ وَسَوۡفَ يُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِينَ أَجۡرًا عَظِيمٗا","aya_text_emlaey":"إلا الذين تابوا وأصلحوا واعتصموا بالله وأخلصوا دينهم لله فأولئك مع المؤمنين وسوف يؤت الله المؤمنين أجرا عظيما","aya_tafseer":"[146] إلا الذين رجعوا إلى الله تعالى وتابوا إليه، وأصلحوا ما أفسدوا من أحوالهم باطناً وظاهراً، ووالَوا عباده المؤمنين، واستمسكوا بدين الله، وأخلصوا له سبحانه، فأولئك مع المؤمنين في الدنيا والآخرة، وسوف يعطي الله المؤمنين ثواباً عظيماً."},{"id":"640","jozz":"5","page":"101","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"14","line_end":"15","aya_no":"147","aya_text":"مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمٗا","aya_text_emlaey":"ما يفعل الله بعذابكم إن شكرتم وآمنتم وكان الله شاكرا عليما","aya_tafseer":"[147] ما يفعل الله بعذابكم إن أصلحتم العمل وآمنتم بالله ورسوله، فإن الله سبحانه غني عمَّن سواه، وإنما يعذَّب العباد بذنوبهم. وكان الله شاكراً لعباده على طاعتهم له، عليماً بكل شيء."},{"id":"641","jozz":"6","page":"102","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"2","aya_no":"148","aya_text":"۞ لَّا يُحِبُّ ٱللَّهُ ٱلۡجَهۡرَ بِٱلسُّوٓءِ مِنَ ٱلۡقَوۡلِ إِلَّا مَن ظُلِمَۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا","aya_text_emlaey":"لا يحب الله الجهر بالسوء من القول إلا من ظلم وكان الله سميعا عليما","aya_tafseer":"[148] لا يُحِبُّ الله أن يَجهر أحدٌ بقول السوء، لكن يُباح للمظلوم أن يَذكُر ظالمه بما فيه من السوء؛ ليبيِّن مَظْلمته. وكان الله سميعاً لما تجهرون به، عليماً بما تخفون من ذلك."},{"id":"642","jozz":"6","page":"102","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"2","line_end":"3","aya_no":"149","aya_text":"إِن تُبۡدُواْ خَيۡرًا أَوۡ تُخۡفُوهُ أَوۡ تَعۡفُواْ عَن سُوٓءٖ فَإِنَّ ٱللَّهَ كَانَ عَفُوّٗا قَدِيرًا","aya_text_emlaey":"إن تبدوا خيرا أو تخفوه أو تعفوا عن سوء فإن الله كان عفوا قديرا","aya_tafseer":"[149] نَدَب الله تعالى إلى العفو، ومَهَّد له بأنَّ المؤمن: إمَّا أن يُظهر الخير، وإمَّا أن يُخفيه، وكذلك مع الإساءة: إما أن يظهرها في حال الانتصاف من المسيء، وإما أن يعفو ويصفح، والعفوُ أفضلُ؛ فإن من صفاته تعالى العفو عن عباده مع قدرته عليهم."},{"id":"643","jozz":"6","page":"102","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"6","aya_no":"150","aya_text":"إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُواْ بَيۡنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤۡمِنُ بِبَعۡضٖ وَنَكۡفُرُ بِبَعۡضٖ وَيُرِيدُونَ أَن يَتَّخِذُواْ بَيۡنَ ذَٰلِكَ سَبِيلًا","aya_text_emlaey":"إن الذين يكفرون بالله ورسله ويريدون أن يفرقوا بين الله ورسله ويقولون نؤمن ببعض ونكفر ببعض ويريدون أن يتخذوا بين ذلك سبيلا","aya_tafseer":"[150] إن الذين يكفرون بالله ورسله، من اليهود والنصارى، ويريدون أن يفرقوا بين الله ورسله بأن يؤمنوا بالله ويكذبوا رسله الذين أرسلهم إلى خلقه، أو يعترفوا بصدق بعض الرسل دون بعض، ويزعموا أنّ بعضهم افتروا على ربِّهم، ويريدون أن يتخذوا طريقاً إلى الضلالة التي أحدثوها والبدعة التي ابتدعوها."},{"id":"644","jozz":"6","page":"102","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"7","aya_no":"151","aya_text":"أُوْلَٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ حَقّٗاۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا","aya_text_emlaey":"أولئك هم الكافرون حقا وأعتدنا للكافرين عذابا مهينا","aya_tafseer":"[151] أُولئك هم أهل الكفر المحقَّق الذي لا شك فيه، وأعتدنا للكافرين عذاباً يُخزيهم ويُهينهم."},{"id":"645","jozz":"6","page":"102","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"9","aya_no":"152","aya_text":"وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦ وَلَمۡ يُفَرِّقُواْ بَيۡنَ أَحَدٖ مِّنۡهُمۡ أُوْلَٰٓئِكَ سَوۡفَ يُؤۡتِيهِمۡ أُجُورَهُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا","aya_text_emlaey":"والذين آمنوا بالله ورسله ولم يفرقوا بين أحد منهم أولئك سوف يؤتيهم أجورهم وكان الله غفورا رحيما","aya_tafseer":"[152] والذين صَدَّقوا بوحدانية الله، وأقرُّوا بنبوَّة رسله أجمعين، ولم يفرقوا بين أحد منهم، وعملوا بشريعة الله، أولئك سوف يعطيهم جزاءهم وثوابهم على إيمانهم به وبرسله. وكان الله غفوراً لعباده رحيماً بهم."},{"id":"646","jozz":"6","page":"102","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"13","aya_no":"153","aya_text":"يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ فَقَدۡ سَأَلُواْ مُوسَىٰٓ أَكۡبَرَ مِن ذَٰلِكَ فَقَالُوٓاْ أَرِنَا ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡهُمُ ٱلصَّٰعِقَةُ بِظُلۡمِهِمۡۚ ثُمَّ ٱتَّخَذُواْ ٱلۡعِجۡلَ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ فَعَفَوۡنَا عَن ذَٰلِكَۚ وَءَاتَيۡنَا مُوسَىٰ سُلۡطَٰنٗا مُّبِينٗا","aya_text_emlaey":"يسألك أهل الكتاب أن تنـزل عليهم كتابا من السماء فقد سألوا موسى أكبر من ذلك فقالوا أرنا الله جهرة فأخذتهم الصاعقة بظلمهم ثم اتخذوا العجل من بعد ما جاءتهم البينات فعفونا عن ذلك وآتينا موسى سلطانا مبينا","aya_tafseer":"[153] يسألك اليهود -أيها الرسول- معجزة مثل معجزة موسى تشهد لك بالصدق: بأن تنزل عليهم صُحُفاً من الله مكتوبةً، مثل مجيء موسى بالألواح من عند الله، فلا تعجب -أيها الرسول- فقد سأل أسلافُهم موسى -عليه السلام- ما هو أعظم: سألوه أن يريهم الله علانيةً، فأخذتهم العقوبة المُهلكة؛ بسبب ظلمهم أنفسهم حين سألوا أمراً ليس من حقِّهم. وبعد أن أحياهم الله بعد الصعق، وشاهدوا الآيات البينات -على يد موسى- القاطعة بنفي الشرك، عبدوا العجل من دون الله، فعَفَونا عن عبادتهم العجل بسبب توبتهم، وآتينا موسى حجة عظيمة تؤيِّد صدق نُبُوَّته."},{"id":"647","jozz":"6","page":"102","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"15","aya_no":"154","aya_text":"وَرَفَعۡنَا فَوۡقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمۡ وَقُلۡنَا لَهُمُ ٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُلۡنَا لَهُمۡ لَا تَعۡدُواْ فِي ٱلسَّبۡتِ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا","aya_text_emlaey":"ورفعنا فوقهم الطور بميثاقهم وقلنا لهم ادخلوا الباب سجدا وقلنا لهم لا تعدوا في السبت وأخذنا منهم ميثاقا غليظا","aya_tafseer":"[154] ورفعنا فوق رؤوسهم جبل الطور حين امتنعوا عن الالتزام بالعهد المؤكد الذي أعطوه بالعمل بأحكام التوراة، وأمرناهم أن يدخلوا باب «بيت المقدس» سُجَّداً، فدخلوا يزحفون على أستاههم، وأمرناهم ألا يَعْتَدُوا بالصيد في يوم السبت، فاعتدَوا وصادوا، وأخذنا عليهم عهداً مؤكداً، فنقضوه."},{"id":"648","jozz":"6","page":"103","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"3","aya_no":"155","aya_text":"فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ وَكُفۡرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتۡلِهِمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَقَوۡلِهِمۡ قُلُوبُنَا غُلۡفُۢۚ بَلۡ طَبَعَ ٱللَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا","aya_text_emlaey":"فبما نقضهم ميثاقهم وكفرهم بآيات الله وقتلهم الأنبياء بغير حق وقولهم قلوبنا غلف بل طبع الله عليها بكفرهم فلا يؤمنون إلا قليلا","aya_tafseer":"[155] فلعنَّاهم بسبب نقضهم للعهود، وكفرهم بآيات الله الدالَّة على صدق رسله، وقتلهم للأنبياء ظلماً واعتداءً، وقولهم: قلوبنا عليها أغطية فلا تفقه ما تقول، بل طمس الله عليها بسبب كفرهم، فلا يؤمنون إلا إيماناً قليلاً لا ينفعهم."},{"id":"649","jozz":"6","page":"103","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"3","line_end":"4","aya_no":"156","aya_text":"وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡيَمَ بُهۡتَٰنًا عَظِيمٗا","aya_text_emlaey":"وبكفرهم وقولهم على مريم بهتانا عظيما","aya_tafseer":"[156] وكذلك لعنَّاهم بسبب كفرهم وافترائهم على مريم بما نسبوه إليها من الزنى، وهي بريئة منه."},{"id":"650","jozz":"6","page":"103","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"7","aya_no":"157","aya_text":"وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِيحَ عِيسَى ٱبۡنَ مَرۡيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِ لَفِي شَكّٖ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ وَمَا قَتَلُوهُ يَقِينَۢا","aya_text_emlaey":"وقولهم إنا قتلنا المسيح عيسى ابن مريم رسول الله وما قتلوه وما صلبوه ولكن شبه لهم وإن الذين اختلفوا فيه لفي شك منه ما لهم به من علم إلا اتباع الظن وما قتلوه يقينا","aya_tafseer":"[157] وبسبب قولهم -على سبيل التهكم والاستهزاء-: إنَّا قتلنا المسيح عيسى بن مريم رسولَ الله، وما قتلوا عيسى وما صلبوه، بل صلبوا رجلاً شبيهاً به ظناً منهم أنه عيسى. ومن ادَّعى قَتْلَه من اليهود، وكذلك مَن أسلمه إليهم من النصارى، كلُّهم واقعون في شك وحَيْرة، لا عِلْمَ لديهم إلا اتباع الظن، وما قتلوه متيقنين بل شاكين متوهمين."},{"id":"651","jozz":"6","page":"103","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"7","line_end":"7","aya_no":"158","aya_text":"بَل رَّفَعَهُ ٱللَّهُ إِلَيۡهِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا","aya_text_emlaey":"بل رفعه الله إليه وكان الله عزيزا حكيما","aya_tafseer":"[158] بل رفع الله عيسى إليه ببدنه وروحه حيّاً، وخلَّصه من الذين كفروا. وكان الله عزيزاً في ملكه، حكيماً في تدبيره وقضائه."},{"id":"652","jozz":"6","page":"103","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"9","aya_no":"159","aya_text":"وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ إِلَّا لَيُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكُونُ عَلَيۡهِمۡ شَهِيدٗا","aya_text_emlaey":"وإن من أهل الكتاب إلا ليؤمنن به قبل موته ويوم القيامة يكون عليهم شهيدا","aya_tafseer":"[159] وإنه لا يبقى أحدٌ من أهل الكتاب بعد نزول عيسى آخر الزمان إلا آمن به قبل موته عليه السلام، ويوم القيامة يكون عيسى -عليه السلام- شهيداً بتكذيب مَن كذَّبه، وتصديق مَن صدَّقه."},{"id":"653","jozz":"6","page":"103","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"11","aya_no":"160","aya_text":"فَبِظُلۡمٖ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِيلِ ٱللَّهِ كَثِيرٗا","aya_text_emlaey":"فبظلم من الذين هادوا حرمنا عليهم طيبات أحلت لهم وبصدهم عن سبيل الله كثيرا","aya_tafseer":"[160] فبسبب ظلم اليهود بما ارتكبوه من الذنوب العظيمة حَرَّم الله عليهم طيبات من المآكل كانت حلالاً لهم، وبسبب صدِّهم أنفسهم وغيرهم عن دين الله القويم."},{"id":"654","jozz":"6","page":"103","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"11","line_end":"12","aya_no":"161","aya_text":"وَأَخۡذِهِمُ ٱلرِّبَوٰاْ وَقَدۡ نُهُواْ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ مِنۡهُمۡ عَذَابًا أَلِيمٗا","aya_text_emlaey":"وأخذهم الربا وقد نهوا عنه وأكلهم أموال الناس بالباطل وأعتدنا للكافرين منهم عذابا أليما","aya_tafseer":"[161] وبسبب تناولهم الربا الذي نهوا عنه، واستحلالهم أموال الناس بغير استحقاق، وأعتدنا للكافرين بالله ورسوله مِن هؤلاء اليهود عذاباً موجعاً في الآخرة."},{"id":"655","jozz":"6","page":"103","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"15","aya_no":"162","aya_text":"لَّٰكِنِ ٱلرَّٰسِخُونَ فِي ٱلۡعِلۡمِ مِنۡهُمۡ وَٱلۡمُؤۡمِنُونَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَۚ وَٱلۡمُقِيمِينَ ٱلصَّلَوٰةَۚ وَٱلۡمُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلۡمُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أُوْلَٰٓئِكَ سَنُؤۡتِيهِمۡ أَجۡرًا عَظِيمًا","aya_text_emlaey":"لكن الراسخون في العلم منهم والمؤمنون يؤمنون بما أنـزل إليك وما أنـزل من قبلك والمقيمين الصلاة والمؤتون الزكاة والمؤمنون بالله واليوم الآخر أولئك سنؤتيهم أجرا عظيما","aya_tafseer":"[162] لكنِ المتمكنون في العلم بأحكام الله من اليهود، والمؤمنون بالله ورسوله، يؤمنون بالذي أنزله الله إليك -أيها الرسول- وهو القرآن، وبالذي أنزل إلى الرسل من قبلك كالتوراة والإنجيل، ويؤدُّون الصلاة في أوقاتها، ويخرجون زكاة أموالهم، ويؤمنون بالله وبالبعث والجزاء، أولئك سيعطيهم الله ثواباً عظيماً، وهو الجنة."},{"id":"656","jozz":"6","page":"104","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"4","aya_no":"163","aya_text":"۞ إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحٖ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَيۡنَآ إِلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيۡمَٰنَۚ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا","aya_text_emlaey":"إنا أوحينا إليك كما أوحينا إلى نوح والنبيين من بعده وأوحينا إلى إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط وعيسى وأيوب ويونس وهارون وسليمان وآتينا داود زبورا","aya_tafseer":"[163] إنا أوحينا إليك -أيها الرسول- بتبليغ الرسالة كما أوحينا إلى نوح والنبيِّين من بعده، وأوحينا إلى إبراهيم وإسماعيل وإسحاق ويعقوب، والأسباط -وهم الأنبياء من ولد يعقوب، الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة- وعيسى وأيوب ويونس وهارون وسليمان. وآتينا داود زبوراً، وهو كتاب وصحف مكتوبة."},{"id":"657","jozz":"6","page":"104","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"4","line_end":"6","aya_no":"164","aya_text":"وَرُسُلٗا قَدۡ قَصَصۡنَٰهُمۡ عَلَيۡكَ مِن قَبۡلُ وَرُسُلٗا لَّمۡ نَقۡصُصۡهُمۡ عَلَيۡكَۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا","aya_text_emlaey":"ورسلا قد قصصناهم عليك من قبل ورسلا لم نقصصهم عليك وكلم الله موسى تكليما","aya_tafseer":"[164] وأرسلنا رسلاً قد قصصناهم عليك في القرآن من قبل هذه الآية، ورسلاً لم نقصصهم عليك لحكمة أردناها. وكلَّم الله موسى تكليماً؛ تشريفاً له بهذه الصفة. وفي هذه الآية الكريمة إثبات صفة الكلام لله -تعالى- كما يليق بجلاله، وأنه سبحانه كلَّم نبيه موسى -عليه السلام- حقيقة بلا واسطة."},{"id":"658","jozz":"6","page":"104","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"7","aya_no":"165","aya_text":"رُّسُلٗا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا","aya_text_emlaey":"رسلا مبشرين ومنذرين لئلا يكون للناس على الله حجة بعد الرسل وكان الله عزيزا حكيما","aya_tafseer":"[165] أرسَلْتُ رسلاً إلى خَلْقي مُبشِّرين بثوابي، ومنذرين بعقابي؛ لئلا يكون للبشر حجة يعتذرون بها بعد إرسال الرسل. وكان الله عزيزاً في ملكه، حكيماً في تدبيره."},{"id":"659","jozz":"6","page":"104","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"8","line_end":"9","aya_no":"166","aya_text":"لَّٰكِنِ ٱللَّهُ يَشۡهَدُ بِمَآ أَنزَلَ إِلَيۡكَۖ أَنزَلَهُۥ بِعِلۡمِهِۦۖ وَٱلۡمَلَٰٓئِكَةُ يَشۡهَدُونَۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا","aya_text_emlaey":"لكن الله يشهد بما أنـزل إليك أنـزله بعلمه والملائكة يشهدون وكفى بالله شهيدا","aya_tafseer":"[166] إن يكفر بك اليهود وغيرهم -أيها الرسول- فالله يشهد لك بأنك رسوله الذي أنْزَلَ عليه القرآن العظيم، أنزله بعلمه، وكذلك الملائكة يشهدون بصدق ما أوحي إليك، وشهادة الله وحدها كافية."},{"id":"660","jozz":"6","page":"104","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"10","aya_no":"167","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ قَدۡ ضَلُّواْ ضَلَٰلَۢا بَعِيدًا","aya_text_emlaey":"إن الذين كفروا وصدوا عن سبيل الله قد ضلوا ضلالا بعيدا","aya_tafseer":"[167] إن الذين جحدوا نُبُوَّتك، وصدُّوا الناس عن الإسلام، قد بَعُدوا عن طريق الحق بُعداً شديداً."},{"id":"661","jozz":"6","page":"104","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"10","line_end":"12","aya_no":"168","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ وَظَلَمُواْ لَمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ طَرِيقًا","aya_text_emlaey":"إن الذين كفروا وظلموا لم يكن الله ليغفر لهم ولا ليهديهم طريقا","aya_tafseer":"[168] إن الذين كفروا بالله وبرسوله؛ وظلموا باستمرارهم على الكفر، لم يكن الله ليغفر ذنوبهم، ولا ليدلَّهم على طريق ينجيهم."},{"id":"662","jozz":"6","page":"104","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"13","aya_no":"169","aya_text":"إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا","aya_text_emlaey":"إلا طريق جهنم خالدين فيها أبدا وكان ذلك على الله يسيرا","aya_tafseer":"[169] إلا طريق جهنم ماكثين فيها أبداً، وكان ذلك على الله يسيراً، فلا يعجزه شيء."},{"id":"663","jozz":"6","page":"104","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"13","line_end":"15","aya_no":"170","aya_text":"يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُواْ خَيۡرٗا لَّكُمۡۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","aya_text_emlaey":"ياأيها الناس قد جاءكم الرسول بالحق من ربكم فآمنوا خيرا لكم وإن تكفروا فإن لله ما في السموات والأرض وكان الله عليما حكيما","aya_tafseer":"[170] يا أيها الناس قد جاءكم رسولنا محمد -صلى الله عليه وسلم- بالإسلام دين الحق من ربكم، فَصَدِّقوه واتبعوه، فإن الإيمان به خير لكم، وإن تُصرُّوا على كفركم فإن الله غني عنكم وعن إيمانكم؛ لأنه مالك ما في السموات والأرض. وكان الله عليماً بأقوالكم وأفعالكم، حكيماً في تشريعه وأمره. فإذا كانت السموات والأرض قد خضعتا لله تعالى كوناً وقدراً خضوع سائر ملكه، فأولى بكم أن تؤمنوا بالله وبرسوله محمد -صلى الله عليه وسلم-، وبالقرآن الذي أنزله عليه، وأن تنقادوا لذلك شرعاً حتى يكون الكون كلُّه خاضعاً لله قدراً وشرعاً. وفي الآية دليل على عموم رسالة نبي الله ورسوله محمد -صلى الله عليه وسلم-."},{"id":"664","jozz":"6","page":"105","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"6","aya_no":"171","aya_text":"يَٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحٞ مِّنۡهُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُواْ ثَلَٰثَةٌۚ ٱنتَهُواْ خَيۡرٗا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَٰهٞ وَٰحِدٞۖ سُبۡحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٞۘ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا","aya_text_emlaey":"ياأهل الكتاب لا تغلوا في دينكم ولا تقولوا على الله إلا الحق إنما المسيح عيسى ابن مريم رسول الله وكلمته ألقاها إلى مريم وروح منه فآمنوا بالله ورسله ولا تقولوا ثلاثة انتهوا خيرا لكم إنما الله إله واحد سبحانه أن يكون له ولد له ما في السموات وما في الأرض وكفى بالله وكيلا","aya_tafseer":"[171] يا أهل الإنجيل لا تتجاوزوا الاعتقاد الحق في دينكم، ولا تقولوا على الله إلا الحق، فلا تجعلوا له صاحبةً ولا ولداً. إنما المسيح عيسى ابن مريم رسول الله أرسله الله بالحق، وخَلَقَه بالكلمة التي أرسل بها جبريل إلى مريم، وهي قوله: «كن»، فكان، وهي نفخة من الله تعالى نفخها جبريل بأمر ربه، فَصدِّقوا بأن الله واحدٌ وأسلموا له، وصدِّقوا رسله فيما جاؤوكم به من عند الله واعملوا به، ولا تجعلوا عيسى وأُمَّه مع الله شريكين. انتهوا عن هذه المقالة خيراً لكم مما أنتم عليه، إنما الله إله واحد سبحانه. ما في السموات والأرضِ مُلْكُه، فكيف يكون له منهم صاحبة أو ولدٌ؟ وكفى بالله وكيلاً على تدبير خلقه وتصريف معاشهم، فتوكَّلوا عليه وحده فهو كافيكم."},{"id":"665","jozz":"6","page":"105","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"6","line_end":"9","aya_no":"172","aya_text":"لَّن يَسۡتَنكِفَ ٱلۡمَسِيحُ أَن يَكُونَ عَبۡدٗا لِّلَّهِ وَلَا ٱلۡمَلَٰٓئِكَةُ ٱلۡمُقَرَّبُونَۚ وَمَن يَسۡتَنكِفۡ عَنۡ عِبَادَتِهِۦ وَيَسۡتَكۡبِرۡ فَسَيَحۡشُرُهُمۡ إِلَيۡهِ جَمِيعٗا","aya_text_emlaey":"لن يستنكف المسيح أن يكون عبدا لله ولا الملائكة المقربون ومن يستنكف عن عبادته ويستكبر فسيحشرهم إليه جميعا","aya_tafseer":"[172] لن يَأْنف ولن يمتنع المسيح أن يكون عبداً لله، وكذلك لن يأنَفَ الملائكة المُقَرَّبون من الإقرار بالعبودية لله تعالى. ومن يأنف عن الانقياد والخضوع ويستكبر فسيحشرهم كلهم إليه يوم القيامة، ويفصلُ بينهم بحكمه العادل، ويجازي كُلّاً بما يستحق."},{"id":"666","jozz":"6","page":"105","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"9","line_end":"12","aya_no":"173","aya_text":"فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡ وَيَزِيدُهُم مِّن فَضۡلِهِۦۖ وَأَمَّا ٱلَّذِينَ ٱسۡتَنكَفُواْ وَٱسۡتَكۡبَرُواْ فَيُعَذِّبُهُمۡ عَذَابًا أَلِيمٗا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا","aya_text_emlaey":"فأما الذين آمنوا وعملوا الصالحات فيوفيهم أجورهم ويزيدهم من فضله وأما الذين استنكفوا واستكبروا فيعذبهم عذابا أليما ولا يجدون لهم من دون الله وليا ولا نصيرا","aya_tafseer":"[173] فأمَّا الذين صَدَّقوا بالله اعتقاداً وقولاً وعملاً، واستقاموا على شريعته فيوفيهم ثواب أعمالهم، ويزيدُهم من فضله، وأما الذين امتنعوا عن طاعة الله، واستكبروا عن التذلل له فيعذبهم عذاباً موجعاً، ولا يجدون لهم وليّاً ينجيهم من عذابه، ولا ناصراً ينصرهم من دون الله."},{"id":"667","jozz":"6","page":"105","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"12","line_end":"13","aya_no":"174","aya_text":"يَٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُم بُرۡهَٰنٞ مِّن رَّبِّكُمۡ وَأَنزَلۡنَآ إِلَيۡكُمۡ نُورٗا مُّبِينٗا","aya_text_emlaey":"ياأيها الناس قد جاءكم برهان من ربكم وأنـزلنا إليكم نورا مبينا","aya_tafseer":"[174] يا أيها الناس قد جاءكم برهان من ربكم، وهو رسولنا محمد -صلى الله عليه وسلم-، وما جاء به من البينات والحجج القاطعة، وأعظمها القرآن الكريم، مما يشهد بصدق نبوته ورسالته الخاتمة، وأنزلنا إليكم القرآن هدىً ونوراً مبيناً."},{"id":"668","jozz":"6","page":"105","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"14","line_end":"15","aya_no":"175","aya_text":"فَأَمَّا ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَٱعۡتَصَمُواْ بِهِۦ فَسَيُدۡخِلُهُمۡ فِي رَحۡمَةٖ مِّنۡهُ وَفَضۡلٖ وَيَهۡدِيهِمۡ إِلَيۡهِ صِرَٰطٗا مُّسۡتَقِيمٗا","aya_text_emlaey":"فأما الذين آمنوا بالله واعتصموا به فسيدخلهم في رحمة منه وفضل ويهديهم إليه صراطا مستقيما","aya_tafseer":"[175] فأمَّا الذين صَدَّقوا بالله اعتقاداً وقولاً وعملاً، واستمسكوا بالنور الذي أُنزل إليهم، فسيدخلهم الجنة رحمة منه وفضلاً، ويوفقهم إلى سلوك الطريق المستقيم المفضي إلى روضات الجنات."},{"id":"669","jozz":"6","page":"106","sura_no":"4","sura_name_en":"An-Nisā’","sura_name_ar":"النِّسَاء ","line_start":"1","line_end":"5","aya_no":"176","aya_text":"يَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِي ٱلۡكَلَٰلَةِۚ إِنِ ٱمۡرُؤٌاْ هَلَكَ لَيۡسَ لَهُۥ وَلَدٞ وَلَهُۥٓ أُخۡتٞ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ يَرِثُهَآ إِن لَّمۡ يَكُن لَّهَا وَلَدٞۚ فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوٓاْ إِخۡوَةٗ رِّجَالٗا وَنِسَآءٗ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ يُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ","aya_text_emlaey":"يستفتونك قل الله يفتيكم في الكلالة إن امرؤ هلك ليس له ولد وله أخت فلها نصف ما ترك وهو يرثها إن لم يكن لها ولد فإن كانتا اثنتين فلهما الثلثان مما ترك وإن كانوا إخوة رجالا ونساء فللذكر مثل حظ الأنثيين يبين الله لكم أن تضلوا والله بكل شيء عليم","aya_tafseer":"[176] يسألونك -أيها النبي- عن حكم ميراث الكلالة، وهو من مات وليس له ولدٌ ولا والد، قل: الله يُبيِّن لكم الحكم فيها: إن مات امرؤ ليس له ولدٌ ولا والد، وله أخت لأبيه وأمه، أو لأبيه فقط، فلها نصف تركته، ويرث أخوها، شقيقاً كان أو لأب جميع مالها إذا ماتت وليس لها ولدٌ ولا والدٌ. فإن كان لمن مات كلالةً أختان فلهما الثلثان مما ترك. وإذا اجتمع الذكور من الإخوة لغير أم مع الإناث فللذكر مثل نصيب الأنثيين من أخواته. يُبيِّن الله لكم قسمة المواريث وحكم الكلالة؛ لئلا تضلوا عن الحقِّ في أمر المواريث. والله عالم بعواقب الأمور، وما فيها من الخير لعباده."}]
